DROP TABLE IF EXISTS `entregas_tareas_cursos_especiales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `entregas_tareas_cursos_especiales` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `tarea_id` int(11) NOT NULL,
  `estudiante_id` int(11) NOT NULL,
  `archivo_nombre` varchar(300) NOT NULL,
  `archivo_path` varchar(500) NOT NULL,
  `fecha_entrega` datetime NOT NULL DEFAULT current_timestamp(),
  `calificacion` decimal(4,2) DEFAULT NULL,
  `comentario_calificacion` text DEFAULT NULL,
  `fecha_calificacion` datetime DEFAULT NULL,
  `visto_por_instructor` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_entrega_esp` (`tarea_id`,`estudiante_id`),
  KEY `estudiante_id` (`estudiante_id`),
  CONSTRAINT `entregas_tareas_cursos_especiales_ibfk_1` FOREIGN KEY (`tarea_id`) REFERENCES `tareas_cursos_especiales` (`id`) ON DELETE CASCADE,
  CONSTRAINT `entregas_tareas_cursos_especiales_ibfk_2` FOREIGN KEY (`estudiante_id`) REFERENCES `estudiantes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

