INSERT INTO `pgo` VALUES (8,4,8,'ANÁLISIS DIFERENCIAL E INTGERAL- GR A','','/uploads/1777503445342-613936503.docx','2026-I','aprobado','','2026-04-29 22:57:25','2026-04-30 03:40:20'),(9,6,8,'ANÁLISIS DIFERENCIAL E INTEGRAL-GR B','','/uploads/1777503923452-307717839.docx','2026-I','aprobado','','2026-04-29 23:05:23','2026-04-30 03:40:07'),(11,7,6,'PGO-C EMPRENDIMIENTOS-GRUPO (A) IDIA','','/uploads/1777563382255-860470037.docx','2026-I','aprobado','','2026-04-30 15:36:22','2026-04-30 15:43:40'),(12,5,6,'PGO-C EMPRENDIMIENTOS-GRUPO (B) IDIA','','/uploads/1777563391448-603018842.docx','2026-I','aprobado','','2026-04-30 15:36:31','2026-04-30 15:43:35'),(13,10,4,'PGO - INGLÉS I','La asignatura de Inglés I tiene como propósito desarrollar en los estudiantes competencias comunicativas básicas en el idioma extranjero, orientadas al uso académico y profesional en el campo de la Innovación Tecnológica e Inteligencia Artificial. El curso proporciona una base sólida en estructuras gramaticales fundamentales, vocabulario general y terminología específica del entorno informático, favoreciendo el desarrollo integrado de las cuatro habilidades lingüísticas: comprensión auditiva, comprensión lectora, producción oral y producción escrita.\r\nSe trabajará a partir de los principios del inglés para Fines Específicos (English for Specific Purposes) y del aprendizaje comunicativo, promoviendo el uso del idioma en contextos reales y significativos. De igual manera, la asignatura busca fortalecer la\r\nautonomía del estudiante en el acceso a información tecnológica en inglés, reconociendo este idioma como lengua predominante en la producción y difusión del conocimiento en este ámbito','/uploads/1778645692021-455013581.pdf','2026-I','enviado',NULL,'2026-05-13 04:14:52',NULL),(14,12,4,'PGO - INGLÉS I','La asignatura de Inglés I tiene como propósito desarrollar en los estudiantes competencias comunicativas básicas en el idioma extranjero, orientadas al uso académico y profesional en el campo de la Innovación Tecnológica e Inteligencia Artificial. El curso proporciona una base sólida en estructuras gramaticales fundamentales, vocabulario general y terminología específica del entorno informático, favoreciendo el desarrollo integrado de las cuatro habilidades lingüísticas: comprensión auditiva, comprensión lectora, producción oral y producción escrita.\r\nSe trabajará a partir de los principios del Inglés para Fines Específicos (English for Specific Purposes) y del aprendizaje comunicativo, promoviendo el uso del idioma en contextos reales y significativos. De igual manera, la asignatura busca fortalecer la autonomía del estudiante en el acceso a información tecnológica en inglés, reconociendo este idioma como lengua predominante en la producción y difusión del conocimiento en este ámbito.','/uploads/1778645762601-924363578.pdf','2026-I','enviado',NULL,'2026-05-13 04:16:02',NULL),(15,8,7,'PLAN GLOBAL OPERATIVO ESTRUCTURAS LÓGICAS - GRUPO A','','/uploads/1778721700239-721688757.pdf','2026-I','enviado',NULL,'2026-05-14 01:21:40',NULL),(16,9,7,'PLAN GLOBAL OPERATIVO DE ESTRUCTURAS LÓGICAS -GRUPO B','','/uploads/1778721771783-91283964.pdf','2026-I','enviado',NULL,'2026-05-14 01:22:51',NULL);
