INSERT INTO `qa_bugs` VALUES (2,'Verificación de accesibilidad lingüística Ingles','Hay campos ambiguos que el propio traductor del navegador no sabe traducir por tanto al intentar traducir ocurre un error lógico. ','1. Ir a la pagina principal de la UNICEN: https://unicen.edu.bo/\n2. Seleccionar traducir del navegador ','Mala traducción del mapa de la barra de navegación\nCampos como COL a BAGGE ','Mala traducción del mapa de la barra de navegación\nCampos como COL a BAGGE ','media','media','nuevo','ui','produccion',32,NULL,NULL,'2026-05-30 10:52:11','2026-05-30 10:54:41'),(3,'Los derechos de Autor no estan actualizados','Al ingresar a la pagina de Unicen y bajar hacia la parte mas baja de la interfaz visual principal se puede observar \" © 2025 UNICEN. Todos los derechos reservados.\". Como se puede observar no esta actualizado el año.','1. Ir a un  navegador.\n2. Poner Unicen en el buscador.\n3. Ingresar a la primera pagina.\n4. Bajar a la parte mas baja de la interfaz visual principal.','Se deberia observar: © 2026 UNICEN. Todos los derechos reservados.','Lo que realmente se pudo observar: © 2025 UNICEN. Todos los derechos reservados.','media','media','nuevo','ui','qa',54,NULL,NULL,'2026-05-30 10:55:14','2026-05-30 10:55:14'),(4,'Recursos de fuentes tipográficas (Montserrat e Inter) rompen con error 404 en la sección de Sedes.','Al navegar en la sección de \"Nuestras Sedes\" (/unicen/sedes/) el sitio web intenta cargar de forma local los archivos de las fuentes tipográficas \"Montserrat\" e \"Inter\". pero las solicitudes al servidor fallan devolviendo un código de estado HTTP 404 (Not Found). Esto obliga al navegador a renderizar el texto con fuentes del sistema por defecto, afectando la consistencia del diseño visual.','Ingresar al sitio web https://unicen.edu.bo/unicen/sedes/.\n\nAbrir las Herramientas de Desarrollador (F12) e ir a la pestaña \"Red\" (Network) o \"Consola\" (Console).\n\nRecargar la página (F5) para capturar todas las peticiones iniciales.\n\nFiltrar por el tipo de recurso \"Fuente\" (Font) u observar los errores marcados en rojo.','Todos los archivos de fuentes vinculados en las hojas de estilo (CSS) deben existir en las rutas especificadas del servidor y retornar un código HTTP 200 (OK) al cargarse.','Las fuentes montserrat.css e inter.css devuelven un error HTTP 404 (Not Found), confirmando que los recursos no se encuentran disponibles en el servidor de producción.','baja','media','nuevo','ui','qa',29,NULL,NULL,'2026-06-05 21:03:09','2026-06-05 21:03:09');
/*!40000 ALTER TABLE `qa_bugs` ENABLE KEYS */;
UNLOCK TABLES;

