INSERT INTO `qa_test_cases` VALUES (1,'Verificar que no sea accesible atraves de distintos lenguajes','El sistema debe ser capaz de interactuar con distintos idiomas','Tener internet, tener un dispositivo para entrar a la pagina Web -  https://unicen.edu.bo/','[\"1.- Tener acceso a internet \",\"2.- Ingresar a la url de unicen\",\"3.- Seleccionar el boton de traduccion\",\"4.-Seleccionar el idioma Ingles\",\"5.-Verificar \\\"Interfaz\\\"\"]','No traduce correctamente a ningun idioma','media','Alfa','bloqueado',NULL,65,9,'2026-05-30 11:17:09','2026-05-30 09:08:53','2026-05-30 11:17:09'),(3,'Verificar visualización correcta de interfaz móvil','Una vez ingresado al sitio web desde un dispositivo móvil verificar que todos los componentes carguen correctamente','1. Tener una computadora o celular                              2. Tener acceso a internet','[\"Tener computadora o celular \",\"Tener acceso a internet\",\"Ingresar a sitio web https://unicen.edu.bo/\"]','La interfaz debe adaptarse correctamente al tamaño de pantalla sin errores visuales ni espacios sobrantes.','media','Grupo Charlie','bloqueado','Esta mal escrito, pasos incompletos  ',48,41,'2026-05-30 10:50:25','2026-05-30 09:16:08','2026-05-30 10:50:25'),(4,'Formularios dificiles de completar en movil','Ingresar a la pagina web -  https://unicen.edu.bo/carreras/derecho-y-ciencias-juridicas/','Entrar desde movil para corroborar el error','[\"1.- Ingresar a la pagina de UNICEN   \",\"2.- ingresar al enlace para acceso mas directo al formulario https://unicen.edu.bo/carreras/derecho-y-ciencias-juridicas/ \",\"3.- intentar llenar el formulario\"]','\nSe le dificulta a los usarios el rellanar los formularios','alta','Alfa','bloqueado','Pasos no bien redactados, no  se especifica el dispositivo movil',65,24,'2026-05-30 10:27:37','2026-05-30 09:17:19','2026-05-30 10:27:37'),(5,'Usos inconsistentes de colores ','Algunas secciones pueden usar colores diferentes sin mantener identidad visual','Pagina de inicio (https://unicen.edu.bo/)','[\"1.-Ingresa a la pagina principal\",\"2.- Deslizar asta el final de la pagina de manera no muy rapida\",\"3.-Observa todos los elementos que tiene la pagina\"]','Apreciar como algunos colores de la pagina muestran mucha diferencia sin mantener identidad visual ni los colores de la universidad','baja','Grupo Alfa','no_ejecutado',NULL,42,NULL,NULL,'2026-05-30 09:18:23','2026-06-03 16:01:32'),(6,'Verificar que el año de los derechos de autor esten actualizados','Una vez ingresado en la pagina de UNICEN nos vamos a la parte final','Tener acceso a internet. ingresar al sitio web https://unicen.edu.bo/','[\"Tener acceso a internet \",\"Ingresamos a la pagina de la unicen\",\"Nos vamos a la parte final de la pagina \",\"Verificamos que los derechos de autor no estan actualizados \"]','Que actualicen el sistema con el año actual ','media','Delta','fallido','Los derechos de autor no estan actualizados',13,54,'2026-05-30 10:18:31','2026-05-30 09:19:11','2026-05-30 10:18:31'),(7,'Verificación de Solicitud de Información con datos lógicamente erróneos','Verificar que la \"Solicitud de Información\" este creada con  la rigidez técnica, \nQue no se vuelva en un campo de spam con información falsa y errónea y también evitar errores lógicos futuros ','Encontrarse en la pagina de la universidad: \nhttps://unicen.edu.bo/\n','[\"Entrar en el modulo/boton  de \\\"Registrate Aqui\\\" \",\"Una vez redirigido, en los espacio que se tienen que poner nombre poner números:\",\"Llenar el resto de los campos con infromacion similar\",\"Enviar el formulario\"]','EL formulario es aceptado sin verificar que los campos donde tiene que ir texto entra números','baja','Delta ','bloqueado',NULL,32,9,'2026-05-30 11:31:52','2026-05-30 09:19:44','2026-05-30 11:31:52'),(8,'Validar  la gestion  ','Al ver la gestion de la pagina se puede observar que no muestra lo que es la gestion actual ','Entrar a la pagina de UNICEN  https://unicen.edu.bo/','[\"Acceso a internet \",\"Entrar a la pagina de la  UNICEN \",\"Bajar hasta la parte final de la pagina \"]','Ver que la gestion no esta actualizada con la gestion actual','baja','Delta ','bloqueado',NULL,24,9,'2026-05-30 11:27:35','2026-05-30 09:21:29','2026-05-30 11:27:35'),(11,'El formulario de registro permite poner numeros en la casilla para ingresar nombre y apellidos ','El registro del formulario no debería aceptar numeros ni signos en la casilla de nombre y apellidos ','1.- Tener internet  2.-Ingresara a la url http://unicen.edu.bo/ ','[\"Hacer click en la opcion de \\\"registrate aqui\\\"\",\"Llenar el formulario \",\"Validar que se puede poner numeros a las casillas de nombre y apellidos \"]','No permitir el ingreso de números en la casilla de nombre y apellido ','media','Grupo Bravo','na','Repite test case ',41,48,'2026-05-30 10:21:38','2026-05-30 09:23:25','2026-05-30 10:21:38'),(12,'Verificar que el formulario de informacion sirva en celular','Una vez ingresado al sitio web desde un dispositivo android dirigirse al acceso de mas informacion y ver si carga las opciones de dicho formulario','1. Tener una computadora o celular                              2. Tener acceso a internet','[\"Tener una computadora o celular\",\"Tener acceso a internet\",\"ingresar al sitio web https://unicen.edu.bo/\"]','Se deberia poder llenar dicho formulario de manera correcta no deberia haber ningun error','media','Grupo Charlie','bloqueado','Los pasos no son muy claros ',48,41,'2026-05-30 10:47:04','2026-05-30 09:24:13','2026-05-30 10:47:04'),(13,'Verificar imagen de la torre empresarial','Objetivo: Encontrar una equivocación en la imagen de la torre empresarial siendo la misma que la torre de salud y en la realidad no se ve de esa manera la torre empresarial','El usuario debe ingresar a la pagina https://unicen.edu.bo/#','[\"Deslizar por la pagina hacia la parte inferior hasta llegar a la información de las sedes que lleva la UNICEN\",\"Observar la imágenes \",\"Comparar la imagen de la torre de salud con la torre empresarial\"]','Que las sedes de ambas sean diferente y realmente verdaderas','media','Charlie','bloqueado',NULL,29,41,'2026-05-30 10:57:22','2026-05-30 09:25:26','2026-05-30 10:57:22'),(14,'Verificar que la página principal cargue correctamente','Validar que el sitio web se cargue sin errores.','Tener acceso a Internet.','[\"1. Abrir navegador.\",\"2. Ingresar la URL: https://unicen.edu.bo/\",\"3. Presionar Enter.\",\"4. Esperar la carga completa.\"]','La página principal debe mostrarse correctamente sin errores.','alta','Alfa','pasado','El Test case cumple con lo formulado',54,19,'2026-05-30 10:37:35','2026-05-30 09:27:10','2026-05-30 10:37:35'),(15,'Verificar Fabiola Quispe ubicación','Una vez ingresado a contactos internacionales buscar el contacto de Fabiola Quispe','1. Tener una computadora o celular                              2. Tener acceso a internet','[\"Tener una computadora o celular\",\"Tener acceso a internet\",\"Ingresar al sitio web https://unicen.edu.bo/\"]','El país y número telefónico de Fabiola Quispe deben coincidir correctamente','media','Grupo Charlie','bloqueado',NULL,48,9,'2026-05-30 11:01:30','2026-05-30 09:31:09','2026-05-30 11:01:30'),(16,'Verificar que el logo de UNICEN sea visible','Validar que el logo institucional aparezca en la página principal.','Sitio cargado correctamente.','[\"1. Abrir navegador\",\"2. Ingresar la URL: https://unicen.edu.bo/\",\"3. Observar la cabecera de la página.\"]','El logo de UNICEN debe visualizarse correctamente.','media','Alfa','pasado','El Test case cumple con lo formulado',54,19,'2026-05-30 10:39:31','2026-05-30 09:31:22','2026-05-30 10:39:31'),(17,'Verificar que en la parte final aparezca el año correcto','Una vez ingresado al sitio web deslizar hasta la parte final del sitio web y fijarse que en año aparezca el correcto','1. Tener una computadora o celular                         \n2. Tener acceso a internet','[\"Tener acceso a internet                                          \",\" Ingresar al sitio web   https://unicen.edu.bo/\",\" Dirigirse a la parte final de la pagina\"]','En la parte final deberia aparecer © 2026 UNICEN. Todos los derechos reservados. ','baja','Grupo Charlie','fallido',NULL,57,9,'2026-05-30 11:00:41','2026-05-30 09:32:26','2026-05-30 11:00:41'),(18,'Superposición del botón flotante de WhatsApp sobre elementos del Footer','El botón flotante de WhatsApp, diseñado para brindar asistencia rápida, se posiciona de forma fija en la esquina inferior derecha. Al hacer scroll por completo hacia el final de la página, este icono tapa de manera absoluta enlaces importantes del pie de página (como políticas de privacidad, teléfonos fijos o redes sociales secundarias), impidiendo que el usuario pueda hacer clic en ellos.','Tener una distribución Windows','[\"Ingresar a la pagina de la UNICEN\",\"Dirigirse a la parte inferior de la pagina \",\"Verificar que el icono de WhatsApp se posicione correctamente \",\"Hacer clic en un banner publicitario interno de la web que redirija a una \\\"Landing Page\\\" de admisiones.\",\"Observar la pestaña del navegador web (Chrome, Edge o Firefox).\"]','El botón de WhatsApp debería tener una regla de CSS que detecte el pie de página y se desplace ligeramente hacia arriba o el footer debería contar con un margen inferior derecho libre para evitar colisiones visuales.','media','Delta','bloqueado',NULL,13,9,'2026-05-30 11:26:39','2026-05-30 09:32:51','2026-05-30 11:26:39'),(19,'Uso de codigo HTML erroneo','Debajo de la parte de \"UNICEN es Noticia\" se puede apreciar numeros que usuarios no tienen idea de que significa','ingresar a la pagina web - https://unicen.edu.bo/      - ','[\"1.- Ingresar pagina de UNICEN    \",\"2.- Deslizar hacia abajo asta pasar el tiltulo de la pagina que dice \\\"UNICEN: Distinciones y condecoraciones nacionales\\\"\",\"3.-Llegar asta el titulo que dice  \\\"UNICEN es Noticia\\\"\",\"4.- Apreciar los numeros que estan debajo de las imagenes del titulo ya mencionado( \\\"UNICEN es Noticia\\\")\"]','Los numeros que se observan es un codigo erroneo de visitas, este mismo no deberia verse en la pagina principal, ya que usuarios podrian malinterpretar las cifras.','alta','Alfa','fallido',NULL,65,9,'2026-05-30 11:14:27','2026-05-30 09:33:08','2026-05-30 11:14:27'),(20,'Verificar la traducción al mismo idioma de origen (Español a Español)','Validar que el sitio de web mantenga su texto original integro y sin alteraciones incorrectas cuando el usuario intenta traducir la pagina al mismo idioma en el que ya se encuentra (Español)','Dispositivo con conexión a internet y navegador web abierto','[\"Ingresar a la pagina principal de UNICEN \",\"Ubicar la opción  o widget de traducción de la página\",\"Seleccionar la opción de traducir al idioma \\\"Español\\\"\",\"Verificar el texto de la interfaz (menú, banners, descripciones)\"]','La pagina debe mantener el texto original en español sin sufrir cambios, traducciones erróneas, alteraciones en las palabras ni pérdida de coherencia ','baja','Delta','fallido',NULL,19,54,'2026-05-30 11:27:11','2026-05-30 09:33:17','2026-05-30 11:27:11'),(21,'Scroll de la pagina demasiado largo','En la pagina de UNICEN, el scroll es demasiado largo, se incorpora mucha información lo cual satura al usuario. ','Entrar a la pagina de UNICEN, en la pagina principal se muestra el scroll es demasiado largo.','[\"1.-Ingresa ala pagina principal ( https://unicen.edu.bo/ )\",\"scroll de abajo hasta arriba, hay mucha pagina \"]','Al entrar a la pagina oficial de UNICEN se llega a apreciar una pagina demasiado larga, al bajar al footer se encuentra con mucha información y satura al usuario. El scroll debería ser lo justo para que el usuario no se sature y pueda tener una interacción agradable','media','Grupo Alfa','bloqueado',NULL,42,9,'2026-05-30 11:12:23','2026-05-30 09:33:27','2026-05-30 11:12:23'),(22,'Verificación del login de los estudiantes ','Validar que el panel login de los estudiantes cumplan con la rigidez técnica que todo login tiene que cumplir antes de entrar a producción \n','Encontrarse en el pagina oficial de la universidad:\nhttps://unicen.edu.bo/','[\"Dirigirse a la esquina superior derecha a la opción SIIA\",\"Una vez encima de la opción se desplegara 3 direcciones entrar al de Estudiantes. \",\"Le redirigirá a la zona estudiantil al cual se accede atravez de un login.\",\"Una vez en el login revisar la URL: http://216.158.233.122:3009/login/\"]','La URL del panel de login envia peticiones http que no tienen cifrado necesaria que un login tiene que contener ante de entrar a produccion, \nEl bajo cifrado de la pagina puede derivar en robo de credenciales ','alta','Delta','bloqueado',NULL,32,9,'2026-05-30 11:23:29','2026-05-30 09:34:50','2026-05-30 11:23:29'),(23,'Verificar funcionamiento del menú principal','Validar que las opciones del menú sean accesibles.','Sitio cargado correctamente.','[\"1. Abrir navegador.\",\"2. Ingresar la URL: https://unicen.edu.bo/\",\"3. Hacer clic en cada opción del menú.\"]','Cada opción debe dirigir a su sección correspondiente.','media','Alfa','pasado','Mala formulación del Test case',54,19,'2026-05-30 10:28:10','2026-05-30 09:35:15','2026-05-30 10:28:10'),(24,'Verificar datos repetidos de Brasil','Una vez ingresado a contactos internacionales revisar información de Brasil','1. Tener una computadora o celular                              2. Tener acceso a internet','[\"Tener una computadora o un celular\",\"Tener acceso a internet\",\"ingresar al sitio web https://unicen.edu.bo/\"]','La informacion de Brasil no debe contener datos repetidos','media','Grupo Charlie','bloqueado','Esta mal escrito los pasos son repetidos ',48,41,'2026-05-30 10:33:50','2026-05-30 09:35:47','2026-05-30 10:33:50'),(25,'Verificar botones de interacción a mas información especifica de \"Estudiantes extrangeros\"','En consultar la información especifica de la carrera','El usuario debe estar en la pagina de https://unicen.edu.bo/#','[\"Pasar el cursor por \\\"Admisiones\\\"\",\"Pasar despues por la seccion \\\"Admisiones Extranjeros\\\"\",\"Entrar a servicios para estudiantes extranjeros\",\"Verificar en los círculos naranjas lleven a la información especifica\"]','Los círculos naranjas deberían llevar a la información especifica para estudiantes extranjeros','alta','Charlie','bloqueado','Esta confirmado que es cierto lo que se dice pero esta mal escrito ',29,41,'2026-05-30 10:32:49','2026-05-30 09:36:40','2026-05-30 10:32:49'),(26,'Inconsistencia en contador estático de años institucionales (Hardcoded Data)','El sistema cuenta con información desactualizada o estática respecto a la edad de la institución. En la sección de antecedentes se calcula matemáticamente que la universidad tiene 36 años (fundada en 1990), pero en los banners principales o imágenes promocionales de la misma sección se visualiza el texto estático \"35 años\".','Tener acceso a internet , ingresar al sitio web https://unicen.edu.bo/','[\"Ir al menú principal > Institucional > Antecedentes.\",\"Leer el segundo párrafo del texto descriptivo.\",\"Comparar el dato con los recursos gráficos/estáticos de la misma página.\"]','Los datos temporales deben ser consistentes, se recomienda reemplazar el texto plano por una variable dinámica: Year(CurrentDate) - 1990.','media','Delta','bloqueado',NULL,13,65,'2026-05-30 10:20:16','2026-05-30 09:39:47','2026-05-30 10:20:16'),(27,'Verificar acceso a la sección \"Carreras\"','Comprobar que la sección de carreras sea accesible.','Sitio cargado correctamente.','[\"1. Abrir navegador.\",\"2. Ingresar la URL: https://unicen.edu.bo/\",\"3. Presionar Enter\",\"4. Seleccionar la opción \\\"Carreras\\\".\"]','Debe mostrarse la información de las carreras disponibles.','media','Alfa','bloqueado','El error no existe y esta mal formulada',54,13,'2026-05-30 10:22:17','2026-05-30 09:41:03','2026-05-30 10:22:17'),(28,'Error al usar zoom en la pagina','Al aumentar, es decir acercar o alejar con el zoom el diseño de la pagina se rompe(se desace)','Acceder a la pagina web - https://unicen.edu.bo/ - desde un celular movil o una laptop','[\"1.- Ingresar a pagina principal  -  https://unicen.edu.bo/\",\"2.- hacer zoom out(alejar) o zoom in(acercar)\",\"3.- apreciar como la pagina en si se rompe o deforma\"]','Al ingresar a la pagina y hacer zoom out o zoom in  se deforma el orden de los enunciados, se mueven de lugar ','media','Alfa','pasado','Se comprobó que el error que existe y la pagina de distorsiona ',65,19,'2026-05-30 10:17:48','2026-05-30 09:42:13','2026-05-30 10:17:48'),(29,'Verificar lo numeros de los numeros internacionales ','El codigo de los  numeros de los contactos internacionales no coincide con sus paises','Pagina de la UNICEN https://unicen.edu.bo/','[\"Internet disponible \",\"Entrar a la pagina UNICEN\",\"Ir a la  parte de admisiones \",\"Hacer click en admisiones extranjeros \",\"Dirigirse a la parte de contactos  \",\"Hacer click en contactos\"]','Se puede observar que los codigos de los numeros extranjeros no coincide con los de su pais ','media','Delta','pasado','Se observa que algunos tiene números y códigos incorrectos ',24,53,'2026-05-30 10:32:10','2026-05-30 09:43:04','2026-05-30 11:04:58'),(30,'Validar que la opcion de contactar al col funcione ','La opcion de contactar al col debería llevarnos hacia el numero del contacto del \"col\"','1.- Tener internet  2.-Ingresara a la urlhttp://unicen.edu.bo//','[\"Hacer click en la parte superior que dice col\",\"Bajar a la parte inferior de la pagina hasta ver la opcion de registrate en el col\",\"Hacer click en la opsion de contacta al col \"]','Contactar con el col para que nos dirija a su numero de contacto','media','Grupo Bravo','bloqueado',NULL,41,9,'2026-05-30 10:54:24','2026-05-30 09:43:06','2026-05-30 10:54:24'),(32,'Verificar login del panel Administrativo','Verificar que el panel de el login cumpla las regulaciones técnicas necesarias antes de entrar a producción ','Encontrarse en la pagina oficial de la universidad: \nhttps://unicen.edu.bo/','[\"Dirigirse a la esquina superior derecha mantener el cursor encima de la opción SIIA \",\"Se le desplegara  3 opciones seleccionar la opcion Administrativos\",\"Una ver redirigido revisar la URL: http://74.50.72.10:3009/login\"]','Que la URL envié peticiones http, \nLas peticiones http no cumplen con un cifrado necesario para un panel de login que pueda entrar a producción.\nPuede derivar en robo de credenciales.','alta','Delta','bloqueado','Jhasim - edito el resultado esperado',32,65,'2026-05-30 10:56:02','2026-05-30 09:43:50','2026-05-30 10:56:02'),(33,'Verificar visualizaciones en la sección de Noticias','No debería de mostrar las visualizaciones de los usuarios en toda la pagina de la UNICEN','El usuario debe estar en la pagina https://unicen.edu.bo/#','[\"Entrar a la sección de noticias dirigido en la parte superior izquierda a lado izquierdo de SEDES\",\"Entrar a cualquier noticia \",\"Desliza hasta encontrar un par de numeros en lo ultimo del texto de la noticia\"]','No debería existir números de las visualizaciones bajo el texto de la noticia','alta','Charlie','bloqueado','No se entiende',29,9,'2026-05-30 10:56:36','2026-05-30 09:46:13','2026-05-30 10:56:36'),(34,'Verificar acceso a la sección \"Contacto\"','Validar que la información de contacto pueda visualizarse.','Sitio cargado correctamente.','[\" Abrir navegador.\",\"Ingresar la URL: https://unicen.edu.bo/\",\"Presionar Enter\",\"Seleccionar \\\"Contacto\\\"\"]','Deben mostrarse los datos de contacto de la universidad.','media','Alfa','bloqueado','La informacion esta mal escrita y los pasos no estan bien definidos ',54,13,'2026-05-30 10:20:27','2026-05-30 09:47:18','2026-05-30 10:20:27'),(36,'Mal diseño de cuadro de interfas de movil','El cuadro de interfaz  esta mal diseñado y no se adapta al formato movil ','1.-Tener internet  2.-Ingresara a la  urlhttp://unicen.edu.bo// ','[\"Ir a la carrera de propaganda publicidad y marketing\",\"Verificar el diseño del cuadro en la vista movil \"]','El cuadro de interfaz debe estar bien diseñado y adaptado correctamente para dispositivos moviles ','baja','Grupo Bravo','bloqueado','Los pasos no estan bien redactados',41,29,'2026-05-30 10:17:12','2026-05-30 09:50:32','2026-05-30 10:17:12'),(37,'Verificar la prevención de pérdida de datos al recargar un formulario en progreso','Validar que el sistema prevenga la pérdida accidental de datos cuando un usuario recarga la página mientras llena un formulario extenso, ya sea reteniendo la información o mostrando una alerta de confirmación','El usuario debe encontrarse en una página de la institución que contenga un formulario extenso','[\"Ingresar a la URL del formulario institucional\",\"Completar parcialmente el formulario (ej. llenar el 90% de los campos requeridos)\",\"Presionar la tecla F5 o hacer clic en el botón de actualizar/recargar del navegador\",\"Observar el comportamiento de la interfaz y los datos ingresados\"]','El sistema debe mostrar una ventana emergente de advertencia nativa del navegador indicando que los cambios no guardados podrían perderse. Alternativamente, si la página se recarga, los datos ingresados previamente deben mantenerse intactos en sus respectivos campos','media','Delta','bloqueado',NULL,19,9,'2026-05-30 11:18:52','2026-05-30 09:54:36','2026-05-30 11:18:52'),(38,'Verificar traduccion del boton SIIA','Una vez ingresado al sitio en idioma traducido revisar el botón','1. Tener una computadora o celular                              2. Tener acceso a internet','[\"Tener una computadora o celular\",\"Tener acceso a internet\",\"Ingresar al sito web https://unicen.edu.bo/\",\"Cambiar idioma\"]','Debe aparecer el nombre correcto del botón y no el texto \"AQUI\"','media','Grupo Charlie','bloqueado',NULL,48,9,'2026-05-30 10:52:05','2026-05-30 09:55:15','2026-05-30 10:52:05'),(39,'Formulario de postulaciones acepta datos invalidos ','El formulario de postulaciones de becas acepta informacion que no deveria permitirce','1.- Tener internet  2.-Ingresara a la  urlhttp://unicen.edu.bo// ','[\"Ingresar a la opcion de registrate aqui \",\"Introducir datos invalidos y enviar el formulario\"]','El formulario debe rechazar datos invalidos o incompletos ','media','Grupo Bravo','bloqueado',NULL,41,9,'2026-05-30 10:51:45','2026-05-30 09:55:56','2026-05-30 10:51:45'),(41,'CP-Col validacion de redireccion fallida en botón \"contactar al col\" ','Existe un fallo de rendimiento en la sección de requisitos de col dentro de la parte wed de Unicen. AL interactuar con el botón de contacto para comunicarse con el asesor ','1 Tener Internet\n2 ingresa a la URL ','[\"Tener acceso a internet\",\"Ingresar a la url de unicen\",\"hacer click en la parte superior que dice col\",\"Deslizar a la opcion requisitos col bajar a la parte inferior de la pagina hasta ver la opcion de rejistrate en el col\",\"Hacer click en la opsion de contacta al col\"]','Que al hacer click en la opcion de contactar con el col nos diriga a su numero de contacto','media','Bravo','bloqueado',NULL,55,9,'2026-05-30 10:50:56','2026-05-30 09:56:36','2026-05-30 10:50:56'),(43,'Verificar Botones de interaccion de \"Certificaciones y Tramites legales\" en la interfaz de movil','En la interfaz de Movil/Celular no es funcional los botones de interacción ','Ingresar https://unicen.edu.bo/# en el Celular','[\"Pasa el cursor en la sección de Unicen\",\"Entrar a Certificaciones y Tramites Legales\",\"Verificar que los botones funcionen correctamente para la informacion\"]','Debería entrar a la información o poder  entrar algún lugar de los botones de interacción','alta','Charlie','bloqueado',NULL,29,9,'2026-05-30 10:48:41','2026-05-30 10:00:09','2026-05-30 10:48:41'),(44,'Identificar El uso de Photoshop en la Portadas de las Sedes','Identificamos  que las fotos de delas Sedes esta siendo photoshopeada, nos damos cuenta que la torre de salud esta siendo photoshopeada en la torre empresarial.','Dentro de la misma pagina, la sede de salud se encuentra en la sede Central','[\"Ingresar al url: https://unicen.edu.bo/\",\"Scrolear/deslizar hacia abajo hasta encontrar las fotos de las Sedes\"]','Deberia mostrar photoshop de la torre de salud en la torre empresarial ','media','ALFA','no_ejecutado',NULL,42,NULL,NULL,'2026-06-03 14:31:05','2026-06-03 14:34:10'),(45,'verificar carreras de UNICEN','verificar que hay  11 carreras ofrecidas en la pagina de UNICEN ','1.Tener internet ','[\"Ir a la pagina https://unicen.edu.bo/\",\"Deslizar el cursor  al encabezado de la pagina cargada donde dice carrera \",\"Hacer clic sobre carreras,  no en el menú desplegable\",\"Esperar a que cargue \",\"Deslizar hacia abajo \",\"Ver que la 11 carreras este en la pagina \"]','Al ingresar a la pagina de UNICEN e ingresar a carreras Y se vean las 11 carreras que ofrece la universidad y 1 programa de formación complementaria','baja','ALFA','no_ejecutado',NULL,53,NULL,NULL,'2026-06-03 14:46:24','2026-06-03 15:41:41'),(46,'Verficar que Interfaz Vsiual de la  pagina esta saturada de Informacion','Identificamos  que En la Pagina de  hay saturación de Información.','Entrar a La pagina de Unicen','[\"Paso 1: Entrar a https://unicen.edu.bo/\",\"Paso 2: Deslizar de arriba a bajo\"]','Se espera que haya un exceso de información en la pagina principal  ','baja','ALFA','no_ejecutado',NULL,42,NULL,NULL,'2026-06-03 14:55:14','2026-06-03 14:55:14'),(47,'Validar la Falta de Modo Oscuro','No ofrece opcion de tema oscuro','Ninguno','[\"Paso 1 :ingresar a  https://unicen.edu.bo/\",\"Paso 2: Revisar en la pagina que no hay modo oscuro\"]','Deben de revisar los alrededores de la pagina y aun asi no encuentras el modo oscuro','baja','ALFA','no_ejecutado',NULL,42,NULL,NULL,'2026-06-03 15:01:46','2026-06-03 15:01:46'),(48,'Verificar el Footer de La pagina Oficial de Unicen','En el footer de la pagina contiene demasiada informacioin lo cual satura y repite varios links',' 	\nhttps://unicen.edu.bo/  o en cualquier \"pestaña\"\n','[\"Paso 1: Entrar a https://unicen.edu.bo/\",\"Deslizar hacia abajo\",\"Revisar el footer de la pagina\"]','En el  footer te encuentras con demasiada  informacion ya repetida','baja','ALFA','no_ejecutado',NULL,42,NULL,NULL,'2026-06-03 15:16:33','2026-06-03 15:16:33'),(49,'Verificar el acceso por el menú desplegable ','En el menú desplegable de la pagina, no ingresa cuando haces clic en el espacio  donde no esta escrita la palabra','Tener acceso a internet ','[\"1.Ir a la pagina https://unicen.edu.bo/\",\"2. Deslizar el cursor  a la barra de navegación de la pagina cargada \",\"3.Poner el cursor sobre posgrado \",\"4.Esperar a que salga el menú desplegable\",\"5.Deslizar hacia abajo del menú despregable\",\"6.Precionar en una de las opciones en el espacio vacio\"]','Al presionar en el espacio vacío de una de las opciones en el menú desplegable no ingresa a lo elegido','media','ALFA','no_ejecutado',NULL,53,NULL,NULL,'2026-06-03 15:23:31','2026-06-03 15:40:35'),(51,'Redireccionamiento ','Al tocar el logo de UNICEN te redireccione a la pagina principal','1.Tener internet \n2.Ingresar a la pagina https://unicen.edu.bo/\n3.Ingresar a cualquier opción de las barra de navegación ','[\"1.Deslizar el cursor a la esquina superior izquierda  encima de el logo UNICEN\",\"2.Hacer clic en el logo UNICEN\"]','Al hacer clic en el logo debe redireccionarte a la pagina principal de UNICEN ','media','ALFA','no_ejecutado',NULL,53,NULL,NULL,'2026-06-03 15:38:55','2026-06-03 15:38:55'),(52,'Verificar la repetición de  las Pestañas de \"Vision, Mision y Filosofia\"','Se repite en 2 links que encuentras en la pagina,  sea en la casilla de unicen en el encabezado o es postgrado repite los mismo párrafos, la única distinción  es por el párrafo de \"Filosofía\".','Entrar a la pagina oficial Unicen','[\"Paso 1: Entrar a https://unicen.edu.bo/\",\"Paso 2: Arrastrar el cursor al Encabezado de la Pagina\",\"Paso 3: Mover el cursor sobre botón \\\"unicen\\\" , luego\",\"Paso 4: Mover cursor sobre botón \\\"postgrado\\\"   \",\"Paso 5: Se verifica en ambas casillas estan con \\\"misión y visión\\\"\",\"Paso 6: al ingresar a cualquiera de los 2 encuentras \\\"misión y visión\\\" repetidos\"]','Al seguir los pasos indicados podemos acceder a ambas pestañas y saber que en ambas hay informacion repetida.','baja','ALFA','no_ejecutado',NULL,42,NULL,NULL,'2026-06-03 15:43:43','2026-06-03 15:43:43'),(53,'Verificar Uso de codigo HTML erroneo','Debajo de la parte de \"UNICEN es Noticia\" se puede apreciar numero que usuarios no tienen idea de que significa','https://unicen.edu.bo/','[\"Paso 1:  Ingresar pagina de UNICEN,  https://unicen.edu.bo/\",\"Paso 2: Deslizar  hacia abajo asta la parte que dice \\\"UNICEN es Noticia\\\" \",\"Paso 3:  Apreciar los numeros que estan debajo del titulo mencionado\"]','El numero que se encuentra en la pagina es un marcador de visita, pero se esta ejecutando de forma errónea ya que el numero puede presentar otro tipo de información','baja','ALFA','no_ejecutado',NULL,42,NULL,NULL,'2026-06-03 15:59:31','2026-06-05 21:50:20'),(54,'Verificar acceso y correcto funcionamiento de la sección \"Bolsa Virtual de Trabajo\"','Validar que el enlace \"Bolsa Virtual de Trabajo\" permita acceder correctamente a la plataforma correspondiente.','El sitio web de UNICEN debe estar disponible y el usuario debe tener acceso a Internet.','[\"Abrir un navegador \",\"Ingresar al sitio web de UNICEN.\",\"Llevar el cursor a la parte de \\\"COL\\\"\",\"Hacer clic dos veces\",\"Realizar desplazamiento vertical hacia la parte baja de la página hasta encontrar la sección \\\"Bolsa Virtual de Trabajo\\\".\",\"Llevar el cursor a \\\"Bolsa Virtual de Trabajo\\\"\",\"Hacer clic  dos veces\"]','El sistema debe redirigir correctamente a la sección de \"Bolsa Virtual de Trabajo\" y mostrar su contenido sin errores.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-03 16:04:22','2026-06-03 16:04:22'),(55,'Usos inconsistentes de colores','Algunas secciones pueden usar colores diferentes sin mantener identidad visual','Pagina de inicio (https://unicen.edu.bo/)','[\"1.-Ingresa a la pagina principal\",\"2.- Deslizar asta el final de la pagina de manera no muy rápida\",\"3.-Observa todos los elementos que tiene la pagina\"]','Apreciar como algunos colores de la pagina muestran mucha diferencia sin mantener identidad visual ni los colores de la universidad','baja','ALFA','no_ejecutado',NULL,65,NULL,NULL,'2026-06-03 16:07:21','2026-06-03 16:07:21'),(56,'Verificacion de redireccionamiento a redes sociales','Ingresando al logo de Facebook te redirecciona a la pagina de UNICEN','1.Tener acceso a Internet ','[\"1.Ir a la pagina https://unicen.edu.bo/\",\"2.Deslizar el cursor a la parte superior izquierda  donde están la redes sociales \",\"3.Hacer clic en el icono de Facebook\",\"4.Esperar a que cargue\"]','debe redireccionar a la pagina de Facebook de UNICEN','baja','ALFA','no_ejecutado',NULL,53,NULL,NULL,'2026-06-03 16:22:17','2026-06-06 09:05:46'),(57,'Verificar el acceso a \"CONTACTAR AL COL\"','Validar que la opción \"CONTACTAR AL COL\" permita acceder correctamente a la sección de contacto correspondiente.','El sitio web de UNICEN debe estar disponible y el usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar al sitio web de UNICEN.\",\"Llevar el cursor a la sección \\\"COL\\\".\",\"Hacer clic dos veces sobre la sección.\",\"Realizar desplazamiento vertical hacia la parte baja de la página hasta encontrar la opción \\\"CONTACTAR AL COL\\\".\",\"Llevar el cursor sobre \\\"CONTACTAR AL COL\\\"\",\"Hacer clic dos veces sobre la opción.\"]','El sistema debe redirigir correctamente al hacer clic la sección \"CONTACTAR AL COL\", mostrando su contenido sin errores de carga ni enlaces rotos.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-03 16:22:21','2026-06-03 16:22:21'),(58,'Verificar acceso a la sección \"REGÍSTRATE\"','Validar que la opción \"REGÍSTRATE\" sea accesible y muestre correctamente su contenido.','El sitio web de UNICEN debe estar disponible y el usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar al sitio web de UNICEN.\",\"Llevar el cursor a la sección \\\"COL\\\"\",\"Hacer clic dos veces sobre la sección\",\"Llevar el cursor sobre \\\"REGÍSTRATE\\\"\",\"Hacer clic dos veces sobre la opción.\"]','El sistema debe mostrar correctamente la sección \"REGÍSTRATE\", permitiendo visualizar su contenido sin errores de navegación o carga.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-03 16:32:31','2026-06-03 16:32:31'),(59,'Verificar acceso a la sección \"REQUISITOS\"','Validar que la opción \"REQUISITOS\" sea accesible y muestre correctamente la información correspondiente.','El sitio web de UNICEN debe estar disponible y el usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar al sitio web de UNICEN.\",\"Llevar el cursor a la sección \\\"COL\\\".\",\"Hacer clic dos veces sobre la sección.\",\"Llevar el cursor sobre \\\"REQUISITOS\\\"\",\"Hacer clic dos veces sobre la opción.\"]','El sistema debe mostrar correctamente la sección \"REQUISITOS\", permitiendo visualizar toda la información correspondiente sin errores de navegación o carga.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-03 16:38:14','2026-06-03 16:38:14'),(60,'Verificar acceso a la sección \"ESTADÍSTICAS EMPLEABILIDAD\"','Validar que la opción \"ESTADÍSTICAS EMPLEABILIDAD\" sea accesible y muestre correctamente la información correspondiente.','El sitio web de UNICEN debe estar disponible y el usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar al sitio web de UNICEN.\",\"Llevar el cursor a la sección \\\"COL\\\".\",\"Hacer clic dos veces sobre la sección.\",\"Llevar el cursor sobre \\\"ESTADÍSTICAS EMPLEABILIDAD\\\".\",\"Hacer clic dos veces sobre la opción.\"]','El sistema debe mostrar correctamente la sección \"ESTADÍSTICAS EMPLEABILIDAD\", permitiendo visualizar la información y estadísticas correspondientes sin errores de navegación o carga.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-03 16:45:37','2026-06-03 16:45:37'),(61,'Verificar el protocolo de la  URL del login de los Estudiantes ','Verificar que el panel de login de los estudiantes de la universidad cumpla con los requisitos técnicos  ','Encontrarse en la pagina oficial de la universidad: https://unicen.edu.bo/','[\"Dirigir el cursor a la parte superior derecha de la pagina principal \",\"Mantener el cursor encima de la opción \\\"SIIA\\\" \",\"Se desplegara 3 opciones \",\"Presionar la opción de \\\"ESTUDIANTES\\\"\",\"Sera redirigido a la pagina de login de los estudiantes \",\"Revisar el protocolo de la URL \"]','El problema principal es la URL del panel de login no esta con el cifrado https si no que esta con el protocolo http. \nResultado: http://216.158.233.122:3009/login/ ','alta','Delta','no_ejecutado',NULL,32,NULL,NULL,'2026-06-04 14:55:36','2026-06-04 16:10:58'),(62,'Validar la consistencia del nombre de la plataforma (SIIA/SIIAA) en el panel de login de estudiantes.','Verificar que el nombre de la plataforma mostrado en la interfaz del panel de login coincida exactamente con el branding oficial (SIIA) y los requisitos de diseño establecidos.','Encontrarse en la pagina oficial de la universidad: \nhttps://unicen.edu.bo/','[\"Dirigirse a la parte superior derecha \",\"Mantener el cursor encima de la opción SIIA\",\"Se desplegaran 3 opciones \",\"Seleccionar la opción de \\\"ESTUDIANTES\\\"\",\"Sera redirigido al panel de login de los estudiantes \",\"Observar la encabezado del login \",\"Validar la consistencia del texto \"]','Verificar que el encabezado muestre el nombre del sistema correspondiente (SIIA / SIIAA) según lo definido en los requerimientos oficiales de la plataforma.','baja','Delta ','no_ejecutado',NULL,32,NULL,NULL,'2026-06-04 15:26:20','2026-06-04 15:42:04'),(63,'Verificar el protocolo de la URL del login de los Administrativos/Docentes','Validar que el protocolo de la URL de login  compartido  de los Administradores y de los Docentes cumpla con los requisitos técnicos \n ','Encontrarse en la pagina oficial de la universidad: \nhttps://unicen.edu.bo/','[\"Dirigir el cursor a la parte superior derecha de la pagina principal \",\"Mantener el cursor encima de la opción \\\"SIIA\\\" \",\"Se desplegara 3 opciones \",\"Presionar la opción de \\\"ADMINISTRATIVOS\\\" o \\\"DOCENTES\\\"\",\"Sera redirigido a la pagina de login de la selección que tomo entre Administrativo o Docente \",\"Revisar el protocolo de la URL\"]','http://74.50.72.10:3009/login\nEl protocolo de la URL del panel login no contiene cifrado SSL ','alta','Delta','no_ejecutado',NULL,32,NULL,NULL,'2026-06-04 16:10:19','2026-06-06 09:17:42'),(64,'Validar el capo de entrada \"Nombre\" de la función  \"REGISTRATE AQUI\"   ','Validar que la función \"REGISTRATE AQUI\" del slider de inicio cumpla con los estandares de calidad de datos ','Encontrarse en el sitio oficial de la universidad: \nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal \",\"Hacer clic en CTA que es el \\\"REGISTRATE AQUÍ\\\"\",\"Seras redireccionado a una URL  Docs de Google \",\"Llegar el campo \\\"Nombre\\\" con números (Ej: juan12321)\",\"Completar el resto de los campos obligatorios del formulario con datos válidos.\",\"Hacer clic en el botón de \\\"Enviar\\\"\"]','El formulario acepta sin validar el contenido en el campo \"Nombre\", aceptando datos de naturaleza errónea como un nombre numérico  ','baja','Delta','no_ejecutado',NULL,32,NULL,NULL,'2026-06-04 18:10:23','2026-06-04 18:30:22'),(65,'Validar el campo de entrada \"Apellido Materno\" de la función \"REGISTRATE AQUÍ\"','Validar que la funcion \"REGISTRATE AQI\" del slider de inicio cumpla con los requisitos de calidad de datos','Encontrase en la pagina oficial de la universidad:\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal \",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\"\",\"Sera redirigido a la URL del formulario de Google Docs\",\"Llenar el campo \\\"Apellido Materno\\\" ingresando caracteres numéricos (Ej: f 123)\",\"Completar el resto de los campos obligatorios del formulario con datos válidos.\",\"Hacer clic en el botón \\\"Enviar\\\".\"]','El formulario acepta sin validar el contenido en el campo \"Apellido\", aceptando datos de naturaleza errónea como un apellido  numérico  ','baja','Delta','no_ejecutado',NULL,32,NULL,NULL,'2026-06-04 18:27:31','2026-06-06 09:14:12'),(66,'Duplicacion de requisitos','En la pagina web \" https://unicen.edu.bo/ \" En el apartado de \"Requisitos\" de las diferentes carreras se duplica la frase de  fotografias 3x4','Dentro de las pestañas de carreras se encuentra \"Requisitos\" y se encuentra un error duplicado en la seccion de extranjeros ','[\"1.- Ingresar a la Pagina de Unicen \\\" https://unicen.edu.bo/ \\\"\",\" 2.- Dirigir el cursor a la parte superior de la pagina (en el encabezado)\",\"3.- Depues de realizar el segundo paso dirigir el cursor al subtitulo carreras\",\"4.-Hacer click en cualquier carrera que aparezca \",\"5.- Deslizar(Scrolear) asta llegar a la parte que dice \\\"Requisitos\\\", esta con letras anaranjadas en la parte lateral izquierda\",\"6.-hacer lectura de los requisitos que piden en la parte de \\\"Estudiantes extranjeros\\\"\",\"7.-En el 4to y 5to requisito se repite \\\"Fotografías tomadas de frente 3×4 Fondo Azul\\\"\"]','Apreciar el errore de la pagina al repetir 2 veces el enuncuado de los requisitos en la parte de \"Requisitos para estudiantes extranjeros\"','media','ALFA','no_ejecutado',NULL,65,NULL,NULL,'2026-06-04 21:03:55','2026-06-04 21:05:58'),(67,'Verificar acceso a la sección \"DESEMPLEO\"','Validar que la opción \"DESEMPLEO\" sea accesible y muestre correctamente la información correspondiente.','El usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar al sitio web de UNICEN.\",\"Llevar el cursor a la sección \\\"COL\\\".\",\"Hacer clic dos veces sobre la sección.\",\"Bajar un poco abajo.\",\"Llevar el cursor sobre \\\"DESEMPLEO\\\".\",\"Hacer clic dos veces sobre la opción.\"]','El sistema debe mostrar correctamente la sección \"DESEMPLEO\", permitiendo visualizar la información correspondiente sin errores de navegación o carga.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-04 21:25:28','2026-06-04 21:25:28'),(68,'Verificar acceso a la sección \"VENTAJAS\"','Validar que la opción \"VENTAJAS\" sea accesible y muestre correctamente la información correspondiente.','El usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar la URL: https://unicen.edu.bo/\",\"Presionar Enter\",\"Llevar el cursor a la sección \\\"COL\\\"\",\"Hacer clic dos veces sobre la sección.\",\"Bajar un poco abajo \",\"Ubicar la opción \\\"VENTAJAS\\\"\",\"Llevar el cursor sobre \\\"VENTAJAS\\\".\",\"Hacer clic dos veces sobre la opción.\"]','El sistema debe mostrar correctamente la sección \"VENTAJAS\", permitiendo visualizar toda la información correspondiente sin errores de navegación o carga.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-04 21:31:41','2026-06-04 21:31:41'),(69,'Verificar reproducción del video \"DRA. ALEJANDRA LANZA\" en la sección \"Testimonios COL\"','Validar que el video \"DRA. ALEJANDRA LANZA\" pueda reproducirse correctamente desde la sección \"Testimonios COL\".','El usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar el URL: https://unicen.edu.bo/\",\"Presionar Enter\",\"Llevar el cursor a la sección \\\"COL\\\".\",\"Hacer clic dos veces sobre la sección.\",\"Bajar abajo\",\"Ubicar la sección \\\"Testimonios COL\\\".\",\"Localizar el video titulado \\\"DRA. ALEJANDRA LANZA\\\".\",\"Hacer un clic sobre el video.\",\"Hacer clic sobre el ícono de reproducción de YouTube ubicado en el centro de la portada del video.\"]','El video \"DRA. ALEJANDRA LANZA\" debe iniciar su reproducción correctamente, sin errores de carga ni reproducción.','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-04 21:44:06','2026-06-04 21:44:06'),(70,'Verificar reproducción del video \"LIC. NAYELI ALONSO\" en la sección \"Testimonios COL\"','Validar que el video \"LIC. NAYELI ALONSO\" pueda reproducirse correctamente desde la sección \"Testimonios COL\".','El usuario debe tener acceso a Internet.','[\"Abrir un navegador.\",\"Ingresar el URL: https://unicen.edu.bo/\",\"Presionar Enter\",\"Llevar el cursor a la sección \\\"COL\\\"\",\"Hacer clic dos veces sobre la sección.\",\"Bajar abajo\",\"Ubicar la sección \\\"Testimonios COL\\\".\",\"Localizar el video titulado \\\"LIC. NAYELI ALONSO\\\"\",\"Hacer un clic sobre el video.\",\"Hacer clic sobre el ícono de reproducción de YouTube ubicado en el centro de la portada del video.\"]','El video \"LIC. NAYELI ALONSO\" debe iniciar su reproducción correctamente, sin errores de carga ni reproducción','media','ALFA','no_ejecutado',NULL,54,NULL,NULL,'2026-06-04 21:48:49','2026-06-04 21:48:49'),(71,'Seguridad / Tipografia','Bloqueo por mixed content al solicitar la fuente roboto atravez de una URL insegura https://','Tener acceso a internet, Ingresar al sitio web https://unicen.edu.bo','[\"Ingresar al sitio web https://unicen.edu.bo       \",\"Ingresar a una de las sedes   \",\"Buscar la ubicacion de cada sedes\"]','Todos los recursos deverian llamarse mediante https:// para cumplir las politicas de seguridad del navegador ','media','Delta','no_ejecutado',NULL,13,NULL,NULL,'2026-06-05 14:18:32','2026-06-05 14:18:32'),(72,'Botones duplicados de envío por doble clic rápido (Double Submit Bug)','En computadoras veloces, si el usuario hace doble clic continuo y rápido sobre el botón \"Enviar formulario\", la página procesa y envía la información dos veces antes de que la pantalla logre congelarse o cambiar.','Tener internet e ir a la ultima fila de la pagina ','[\"Entrar a la pagina https://unicen.edu.bo\",\"Ir hasta el final de la pagina\",\"Completar un formulario de contacto\",\"Hacer un doble clic muy rápido sobre el botón de envío\"]','En cuanto el usuario hace el primer clic, el botón debe cambiar a un estado deshabilitado (disabled=\"true\") mediante JavaScript mientras dura el proceso de carga.','media','Delta','no_ejecutado',NULL,13,NULL,NULL,'2026-06-05 14:23:17','2026-06-05 14:23:17'),(73,'Desincronización horaria en los banners de cuenta regresiva (Timezone Desync)','Si la universidad publica un reloj en cuenta regresiva para el \"Cierre de inscripciones\", el tiempo restante se calcula usando la hora local de la computadora del usuario en lugar de la hora oficial del servidor de la universidad.','tener internet, Ingresar al sitio web https://unicen.edu.bo','[\"Ingresar al sitio web https://unicen.edu.bo\",\"Observar el reloj de cuenta regresiva en la web.\",\"Cambiar la zona horaria o la hora interna de tu computadora desde el panel de control de Windows.\",\"Refrescar la página web.\"]','El cálculo de tiempo restante debe hacerse en base a una petición a la API del servidor (Server Time) para que sea idéntico para todos los usuarios independientemente de su computadora.','media','Delta','no_ejecutado',NULL,13,NULL,NULL,'2026-06-05 14:26:47','2026-06-05 14:26:47'),(74,'Persistencia de datos al fallar el envío del formulario','Comprobar que la UI no borre los datos ya escritos si ocurre un error menor.','Tener internet, Ingresar al sitio web https://unicen.edu.bo','[\"Ingresar al sitio web https://unicen.edu.bo\",\"Ir al final de la pagina\",\"Rellenar todo el formulario de contacto.\",\"Colocar un correo inválido de adrede.\",\"Presionar Enviar y esperar el error.\"]','El sistema debe mostrar el mensaje de error de correo, pero retener los textos ya escritos en los campos de Nombre y Teléfono.','media','Delta','no_ejecutado',NULL,13,NULL,NULL,'2026-06-05 14:30:24','2026-06-05 14:30:24'),(75,'Validación de extensión de imagen de perfil','Probar las restricciones de formatos permitidos en cargas de archivos de soporte.','Tener internet, Ingresar al sitio web https://unicen.edu.bo','[\"Ingresar al sitio web https://unicen.edu.bo\",\"Ir al final de la pagina\",\"Dirigirse al formulario que permita adjuntar documentos o fotos.\",\"Intentar subir un archivo de texto .txt en un campo exclusivo para fotos.\"]','El sistema debe impedir la carga mostrando el mensaje: \"Formato de archivo no válido. Solo se permite JPG o PNG\".','media','Delta','no_ejecutado',NULL,13,NULL,NULL,'2026-06-05 14:34:29','2026-06-05 14:34:29'),(76,'Repeticion execiba de las sede y subsedes de la univesidad','Al ingresar a la pagina \" https://unicen.edu.bo/ \" se puede apreciar al deslizar(Scrolear)asta la parte baja de la pagina las imagenes de las sedes y subcedes, al ingresar al cualquier otra opcion del encabezado y deslizar asta abajo se repite las imagenes .','Tener acceso a internet, ingresar a la pagina web \" https://unicen.edu.bo/ \"','[\"1.- Ingresar a la pagina web \\\" https://unicen.edu.bo/ \\\"\",\"2.- Scrolear hacia abajo asta apreciar las sedes y subsedes \",\"3.- Volver a scrolear asta el pricipio(arriba)\",\"4.- Dirigir el cursor a la parte superior de la pagina(el encabezado)\",\"5.- Hacer click en cualquiera de las opciones que se encuentran en el encabezado \\\"Unicen, Carreras, Admisiones, Postgrado, Programa Complementario, COL\\\"\",\"6.- Deslizar la pantalla hacia abajo asta apreciar las sedes y subsedes de UNICEN\",\"7.- Repetir los pasos desde  el paso 4 con los diferentes subtitulos ya  mencionados \\\" Unicen, Carreras, Admisiones, Postgrado, Programa Complementario, COL \\\"\"]','Apreciar la execiva repeticion y/o duplicacion de las Sedes y Subsedes en la pagina web','media','ALFA','no_ejecutado',NULL,65,NULL,NULL,'2026-06-05 19:18:48','2026-06-05 19:18:48'),(77,'Validar caracteres numéricos en campo de \"Apellido Paterno\" de la función \"REGISTRATE AQUÍ\"','Verificar que el campo \"Apellido Paterno\" impida el ingreso y envío de datos puramente numéricos. ','Tener cargada la pagina de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\" para ingresar al formulario de Google Docs\",\"Llenar el campo \\\"Apellido Paterno\\\" ingresando caracteres numéricos (Ej. 1234)\",\"Completar el resto de los campos obligatorios del formulario con datos validos \",\"Hacer clip en el botón de \\\"Enviar\\\"\"]','El sistema debe validar el campo y desplegar una alerta de error que indique: \"El apellido paterno no puede contener solo números\" o \"Formato inválido\".','media','Delta','fallido','Fallo de validación: El campo \"Apellido Paterno\" acepta caracteres numéricos independientes y permite continuar con el registro de la solicitud sin lanzar advertencias de formato inválido.',19,19,'2026-06-11 22:27:49','2026-06-05 19:28:23','2026-06-11 22:27:49'),(78,'Verificar ingreso y envío de datos numéricos en el campo  \"Otro\" para departamentos de la función \"REGISTRATE AQUÍ\"','Verificar que la opción \"Otro\" en la selección de departamentos impida el ingreso de datos numéricos','Tener cargada la pagina de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la página principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\" para ingresar al formulario de Google Docs\",\"Llenar el campo \\\"Otro\\\" para departamentos,  ingresando caracteres numéricos (Ej. 1234)\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\"\"]','El sistema debe validar el campo y desplegar una alerta de error que indique: \"El campo OTRO  no puede contener solo números\" o \"Formato inválido\". ','media','Delta','fallido','Fallo de validación: El campo \"Otro\"  de departamentos acepta caracteres numéricos independientes y permite continuar con el registro de la solicitud sin lanzar advertencias de formato inválido.',19,19,'2026-06-11 22:27:07','2026-06-05 19:41:55','2026-06-11 22:27:07'),(79,'Validar texto alfabético en campo de \"Celular/Teléfono\" de la función \"REGISTRATE AQUÍ\"','Verificar que el campo \"Celular/Teléfono\" impida el ingreso de letras o texto plano.','Tener cargada la página de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\" para ingresar al formulario de Google Docs\",\"Llenar el campo \\\"Celular/Teléfono\\\" ingresando caracteres de texto alfabético (Ej. Hola)\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\"\"]','El sistema debe validar el campo y desplegar una alerta de error que indique: \"El Celular/Teléfono no puede contener solo texto alfabético\" o \"Formato inválido\".','media','Delta','fallido','Fallo de validación de datos: El campo \"Celular/Teléfono\" acepta texto plano y letras, permitiendo que el usuario avance sin lanzar advertencias de formato inválido ni exigir caracteres estrictamente numéricos.',19,19,'2026-06-11 22:25:39','2026-06-05 19:57:35','2026-06-11 22:25:39'),(80,'Verificacion de redireccionamiento a redes sociales',' Ingresando al logo de Instagram te redirecciona a la pagina de UNICEN','1.Tener acceso a Internet','[\"1.Ir a la pagina https://unicen.edu.bo/\",\" 2.Deslizar el cursor a la parte superior izquierda  donde están la redes sociales\",\"3.Hacer clic en el icono de Instagram\",\"4.Esperar a que cargue\"]','Debe ingresar a la pagina de Instagram de UNICEN','baja','ALFA','no_ejecutado',NULL,53,NULL,NULL,'2026-06-05 20:01:31','2026-06-06 09:13:32'),(81,'Verificar cronología de Fecha de Nacimiento futura de la función \"REGISTRATE AQUÍ\"','Verificar que el campo \"Fecha de Nacimiento\" bloquee el registro de fechas posteriores al día actual.','Tener cargada la página de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\" para ingresar al formulario de Google Docs\",\"Ir a la sección \\\"Fecha de Nacimiento\\\" del formulario.\",\"Digitar o seleccionar una fecha que pertenezca a un año futuro.\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\"\"]','El sistema debe validar el rango cronológico e impedir el avance, mostrando un error como: \"La fecha de nacimiento no puede ser futura\".','media','Delta','fallido','Error de lógica: El campo \"Fecha de Nacimiento\" carece de validación temporal, permitiendo que el usuario digite y procese fechas futuras (posteriores al año en curso) sin emitir ninguna advertencia de formato inválido.',19,19,'2026-06-11 22:24:15','2026-06-05 20:05:29','2026-06-11 22:24:15'),(82,'Verificacion de redireccionamiento a redes sociales',' Ingresando al logo de X te redirecciona a la pagina de UNICEN',' 1.Tener acceso a Internet','[\"1.Ir a la pagina https://unicen.edu.bo/\",\"2.Deslizar el cursor a la parte superior izquierda  donde están la redes sociales\",\"3.Hacer clic en el icono de X\",\"4.Esperar a que cargue\"]','Debe ingresar a la pagina de X de UNICEN','baja','ALFA','no_ejecutado',NULL,53,NULL,NULL,'2026-06-05 20:05:41','2026-06-06 09:13:02'),(83,'Verificacion de redireccionamiento a redes sociales',' Ingresando al logo de Tik tok te redirecciona a la pagina de UNICEN',' 1.Tener acceso a Internet','[\" 1.Ir a la pagina https://unicen.edu.bo/\",\"2.Deslizar el cursor a la parte superior izquierda  donde están la redes sociales\",\"3.Hacer clic en el icono de Tik tok\",\"4.Esperar a que cargue\"]','Debe ingresar a la pagina de Tik tok de UNICEN','baja','ALFA','no_ejecutado',NULL,53,NULL,NULL,'2026-06-05 20:10:58','2026-06-06 09:11:24'),(84,'Verificar ingreso de texto alfabético en campo de \" Edad\" de la función \"REGISTRATE AQUÍ\"','Verificar que el campo obligatorio \"Edad\" impida el ingreso de letras o texto plano','Tener cargada la pagina de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al slider de la pagina principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUÍ\\\" para ingresar al formulario de Google Docs\",\"Llenar en campo \\\"Edad\\\" ingresando caracteres de texto alfabético\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\" \"]','El sistema debe validar el formato numérico y desplegar una advertencia en pantalla que exija introducir un número entero y no permita texto alfabético','media','Delta','fallido','Fallo de validación de datos: El campo \"Edad\" acepta texto plano y letras, permitiendo que el usuario avance sin lanzar advertencias de formato inválido ni exigir caracteres estrictamente numéricos.',19,19,'2026-06-11 22:22:21','2026-06-05 20:18:50','2026-06-11 22:22:21'),(85,'Validar caracteres numéricos en campo \"Nombre del colegio\" de la función \"REGISTRATE AQUÍ\"','Verificar que el campo \"Nombre del colegio en el que estudió\" impida el ingreso de datos puramente numéricos ','Tener cargada la página de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\" para ingresar al formulario de Google Docs\",\"Llenar el campo \\\"Nombre del colegio en el que estudió\\\" ingresando caracteres numéricos (Ej. 1234)\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\" \"]','El formulario debe validar la entrada para asegurar que se ingrese un nombre textual válido de institución educativa, bloqueando valores solo numéricos.','media','Delta','fallido','Fallo de validación: El campo \"Nombre del colegio\" acepta caracteres numéricos independientes y permite continuar con el registro de la solicitud sin lanzar advertencias de formato inválido.',19,19,'2026-06-11 22:18:44','2026-06-05 20:33:20','2026-06-11 22:18:44'),(86,'Validar texto en opción abierta \"Otro\" para tipo de colegio de la función \"REGISTRATE AQUÍ\"','Verificar que la opción abierta \"Otro\" en la sección \"Su colegio es\" impida el ingreso de datos numéricos.','Tener cargada la pagina de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\" para ingresar al formulario de Google Docs\",\"Ir a la sección obligatoria \\\"Su colegio es:\\\".\",\"Seleccionar la casilla \\\"Otro:\\\"\",\"Llenar el campo \\\"Otro\\\"  de su colegio es, ingresando caracteres numéricos (Ej. 1234)\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\" \"]','La opción \"Otro\" debe contar con una validación de formato que obligue al usuario a ingresar una descripción textual válida y coherente sobre el tipo de colegio, bloqueando números sueltos.','media','Delta','fallido','Fallo de validación: El campo \"Otro\" para tipo de colegio acepta caracteres numéricos independientes y permite continuar con el registro de la solicitud sin lanzar advertencias de formato inválido.',19,19,'2026-06-11 22:17:01','2026-06-05 20:41:14','2026-06-11 22:17:01'),(87,'Validar texto numérico en campo \"Carrera a estudiar\" de la  función \"REGISTRATE AQUÍ\"','Verificar que el campo \"Carrera a estudiar\" restrinja el ingreso de datos numéricos incoherentes o sin sentido.','Tener cargada la pagina de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la pagina principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUI\\\" para ingresar al formulario de Google Docs\",\"Llenar el campo \\\"Carrera a estudiar\\\" ingresando caracteres numéricos (Ej. 1234)\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\" \"]','El formulario debería validar la entrada exigiendo un nombre de carrera legítimo o que no permita el ingreso de números','media','Delta','fallido','Fallo de validación: El campo \"Carrera a estudiar\" acepta caracteres numéricos independientes y permite continuar con el registro de la solicitud sin lanzar advertencias de formato inválido.',19,19,'2026-06-11 22:15:05','2026-06-05 20:56:55','2026-06-11 22:15:05'),(88,'Verificar el Error de Ajuste de Pantalla (Margen Blanco en el Borde Derecho)','Al abrir la página web de unicen  en un dispositivo móvil, el diseño no se adapta correctamente al ancho de la pantalla en este caso lo ise con un infinix 12 pro y  Se genera un espacio en blanco innecesario en todo el borde derecho','https://unicen.edu.bo/','[\"Abrir el navegador Chrome \",\"Ingresar a ala página de unicen \",\"Cargar la página principal: Espera a que el sitio web cargue completamente.\",\"Observar el diseño visual: Revisa el borde derecho de la pantalla. Notarás de inmediato la franja blanca que sobra y que el banner azul no llega hasta el final del borde derecho.\",\"Intentar deslizar hacia los lados: Coloca tu dedo en la pantalla e intenta deslizar la página hacia la izquierda y derecha. Verás cómo la página \\\"baila\\\" y se mueve hacia los lados debido a ese espacio extra.\"]','Lo que esperamos ver es que la página se ajuste perfectamente al ancho de la pantalla del  celular. No debería haber ningún espacio en blanco en el lado derecho ni ningún tipo de borde raro.\n','baja','Delta','no_ejecutado',NULL,21,NULL,NULL,'2026-06-05 21:33:43','2026-06-10 03:29:54'),(89,'Verificar la existencia de contenido duplicado y numeración incorrecta en los requisitos de admisión a  extranjeros','En la sección de requisitos de admisión a extranjeros de la página web de unicen, el cuarto requisito se muestra duplicado. Hay dos recuadros seguidos con el número 4 que piden exactamente lo mismo Fotografías tomadas de frente 3×4 Fondo Azul.','https://unicen.edu.bo/','[\"Abrir el navegador web Chrome \",\"Ingresa a la página de unicen \",\"Entra al menú: ingresar al apartado de administración y luego a extranjeros, luego a requisitos \",\"Deslizar hacia abajo : Mueve tu dedo de abajo hacia arriba en la pantalla para bajar por la página hasta encontrar la sección donde se listan los  requisitos necesarios para inscribirse.\",\"Leer la lista numerada con atención: Detén el deslizamiento cuando llegues a los recuadros azules numerados. Mira detenidamente el orden de los círculos naranjas con números y el texto que llevan dentro.\",\"Verificar  el contenido duplicado  \"]','Lo que tendría que pasar es que la lista de requisitos sea consecutiva y ordenada. Cada recuadro debe tener un número único y mostrar un documento diferente, sin repetir información ni duplicar los recuadros azules.','media','Delta','fallido','En la sección de requisitos de admisión para estudiantes extranjeros, se presenta un error de duplicidad en la interfaz de usuario . El requisito número 4 aparece repetido de forma idéntica en dos recuadros consecutivos, manteniendo el mismo número correlativo. Esto evidencia un error en el bucle de renderizado de datos o una carga duplicada en el backend/base de datos del sitio, afectando la claridad de la información y la estética de la página.',21,55,'2026-06-07 22:22:47','2026-06-05 21:55:13','2026-06-10 03:27:05'),(90,'verificar  si menú de carreras la Carrera \"Trabajo Social\"  no aparece','la carrera no existe en la sección Carreras del sitio. Genera confusión al usuario.','Tener acceso a unicen.edu.bo y al menú principal de Carreras.','[\"abrir la pagina web\",\"el curso va a la parte superior sobre la pestaña de carreras \",\"buscamos las opciones de aparecen la carrera de trabajo social\",\"Verificar si \\\"Trabajo Social\\\" aparece en la lista\"]','la carrera de tabajo social tendria que salir en al ofecarta academica dado que es una carrera ','media','delta','no_ejecutado',NULL,16,NULL,NULL,'2026-06-05 22:04:41','2026-06-09 22:27:12'),(91,'verificar enlace del botón \"Regístrate aquí\" redirige a Google Forms externo sin aviso','El botón \"Regístrate aquí\"  lleva a forms sin notificar al usuario que saldrá del sitio oficial. No hay formulario integrado en la plataforma propia.','contar con un dispositivo con conectividad a internet, tener la direccion de la pagina: https://unicen.edu.bo/\n\n','[\"abrimos la pagina web, en la parte superior \",\"Hacer clic en el botón \\\"Regístrate aquí\\\" del banner principal\",\"Verificar a qué dominio redirige\",\"Comprobar si hubo algún aviso de redirección externa\",\"entrar al formulario\"]','El sitio debería avisar al usuario cuando lo redirige a un dominio externo, o el formulario debería estar integrado en la plataforma propia.','media','delta','fallido','Al hacer clic en el botón \"Regístrate aquí\", el sitio web redirige automáticamente al usuario hacia un formulario externo de Google Forms interrumpiendo abruptamente la navegación dentro del portal oficial de UNICEN y generando desconfianza en el usuario al no haber una advertencia previa de que está abandonando el sitio institucional para ingresar sus datos personales en una plataforma externa',16,55,'2026-06-07 22:11:34','2026-06-05 22:07:40','2026-06-09 22:29:35'),(95,'verificar cursos de posgrado no aclaran ','En unicen.edu.bo/postgrado/oferta/ la sección \"Todos los programas\" lista diplomados y maestrías con fechas de inicio de 2025 (octubre, noviembre, agosto), que ya pasaron. Ninguno tiene etiqueta de estado (finalizado, en curso, próximamente). El usuario no puede saber si aún puede inscribirse, si el curso ya terminó, o si son solo datos históricos. La sección \"Programas a iniciar\" solo muestra 1 curso (11/06/2026), lo que genera la impresión de que casi no hay oferta activa.','Acceder a unicen.edu.bo/postgrado/oferta/ desde cualquier navegador. La fecha actual debe ser posterior a octubre 2025.','[\" Ir a unicen.edu.bo/postgrado/oferta/\",\"Revisar la sección \\\"Programas a iniciar\\\" y anotar cuántos cursos aparecen\",\"Bajar a la sección \\\"Todos los programas\\\" y revisar las fechas de inicio de cada curso\",\"Verificar si algún curso tiene etiqueta de estado (activo, finalizado, próximo, etc.)\",\"Intentar ingresar a un curso con fecha pasada para ver si aún permite inscripción\"]','Cada programa debe mostrar claramente su estado actual: \"Inscripciones abiertas\", \"En curso\", \"Finalizado\" o \"Próximamente\". Los programas ya vencidos no deberían aparecer en la sección principal de oferta activa, o si se muestran como historial, deben estar claramente diferenciados.','alta','delta','bloqueado','mucha redundancia',16,41,'2026-06-06 09:52:52','2026-06-05 23:06:56','2026-06-09 21:35:33'),(96,'verificar falta de validación de información de Gmail para enviar formularios','el sitio web cuenta con un cuestionario rápido y fácil envió pero la información que envíes no esta con precondiciones anbiguas. lo cual genera información errónea critica si la pagina cuanta con trafico masivo','contar con un dispositivo con conectividad a internet, tener la direccion de la pagina: https://unicen.edu.bo/','[\"ingresamos a la pagina web\",\"nos deplazamos el cursor hasta la parte inferior de la pagina. \",\"encontraremos un formulario con varios espacios en blanco\",\"ingresamos valores aleatorios en el gmail\",\"con servamos el @gmail.com para cumplir con la condicion general de un gmail.\",\"observamos que desaparece la advertencia de gmail. valido\",\"una vez tengamos todos los datos llenados procedemos a  enviar\",\"nos dirigimos y seleccionamos el boton quiero mas informacion\",\"nos informan que el cuestionario fue enviado correctamente\"]','con la corrección de este bug, nos aseguramos que que el formulario tendrá datos validos. para enviar la información correspondiente que solicitaron','alta','delta','bloqueado','No se entiende mucho los pasos',16,41,'2026-06-06 09:51:27','2026-06-05 23:23:26','2026-06-09 21:32:03'),(97,'verifica la falta de filtros predeterminados basados en el tiempo ','En la sección de noticias aparecen artículos propios de UNICEN el buscador solo cuentas con pestañas predeterminadas de tematicas, no cuenta apartados de hoy , reciente, este mes, este año.','contar con un dispositivo con conectividad a internet, tener la direccion de la pagina: https://unicen.edu.bo/','[\"desde el navegador  inglesamos a la pagina de unicen\",\"dirigimos el cursor a la parte superior derecha y selecionamos el boton de noticias\",\"la pagina despliega el area de noticias, \",\"la noticias solo cuentan con titulo e imagen.\",\"en la parte lateral derecha encontramos opciones predeterminadas de busqueda. \",\"se puede apreciar la ausencia de apartados de hoy, esta semana, este mes y este año. \",\"conforme desplazamos el cursor notamos que si contamos con el espacio suficiente para añadirlos\"]','mejorar la busque da noticias cuando se requiera, mejoraremos la experiencia de usuario con apartados pensados en el. ','media','delta','bloqueado',NULL,16,41,'2026-06-06 09:49:14','2026-06-05 23:24:49','2026-06-09 21:15:58'),(98,'Verificar la existencia del Error de Traducción y Formato en la Carrera de Medicina (\"Medicamento\")','En la pestaña o sección de  CARRERAS de la página web de unicen, cuando el navegador o el sistema intenta traducir el sitio, la carrera de Medicina se muestra mal traducida muestra  la palabra  Medicamento a la hora de traducir la página al español','https://unicen.edu.bo/','[\"Entra al navegador  Chrome\",\"Ingresa a la página de unicen \",\"En el caso de un teléfono móvil presiona los 3 puntitos que aparecen en  la parte superior derecha de la pantalla  y busca el apartado que dise  traducir \",\"La traducción tiene que estará al español \",\"Luego ve deslizando asia abajo y busca la sección de carreras \",\"Busca la carrera de medicina \",\"Verifica que no aparece la palabra de medicina sino que la traducción  dise medicamento en su lugar \"]','Lo que debería pasar es que, aun cuando la página sea traducida por el navegador, el nombre de la carrera se muestre de forma correcta como \"Medicina\".','baja','Delta','pasado',NULL,21,41,'2026-06-06 09:23:34','2026-06-06 04:39:07','2026-06-09 21:04:12'),(100,'Verificar la existencia de una Línea Blanca con Números en la Sección de Bolsa de Trabajo','Al navegar en la sección de \"Bolsa de Trabajo\" en  la página  de unicen , aparece una línea blanca horizontal que interrumpe,Dentro de esta línea se muestran números.','https://unicen.edu.bo/','[\"Abrir el Navegador Chrome \",\"Entra a la página de unicen  y espera a que cargue \",\"Entra la menú, luego al apartado de col y luego al apartado de bolsa de trabajo \",\"Ve deslizando la pantalla asia abajo \",\"Veras que arriba del enunciado que dice regístrate en el col  se encuentra una linea blanca con números \",\"Verifica la existencia de la linea blanca con números \"]','Lo que debería ocurrir es que el diseño de fondo azul oscuro de la página se mantenga de manera continua y uniforme.','baja','Delta','bloqueado',NULL,21,41,'2026-06-06 09:22:16','2026-06-06 05:14:02','2026-06-09 20:52:21'),(101,'Verificar que el botón \"CONTACTA AL COL\" no Funciona correctamente ','En la sección del centro de oportunidades laborales de la página web de unicen , el botón que dice \"CONTACTA AL COL\" no realiza ninguna acción al ser presionado.','https://unicen.edu.bo/','[\"Abrir el navegador: Toca el icono de tu navegador web\",\"Entra a l página de unicen y espera a que cargue \",\"Entra al menú ,luego al apartado de col y por último al apartado de  estadísticas de desempleo \",\"Ve deslizando la pantalla asia abajo asta encontrar el botón que dise contacta al col\",\"Presiona el botón y espera \",\"Verifica que el botón no funciona correctamente \"]','Al presionar el botón \"CONTACTA AL COL\", la página debería abrir de inmediato un canal de comunicación.','media','Delta','bloqueado',NULL,21,41,'2026-06-06 09:16:51','2026-06-06 05:34:47','2026-06-09 20:43:29'),(102,'Verificar que los botones de \"REGÍSTRATE\" y \"REQUISITOS\" están inactivos en la sección del centro de oportunidades laborales','En la pantalla informativa del centro de oportunidades laborales, los dos botones ubicados debajo de la lista de beneficios están completamente inactivos. Al presionarlos  la página no reacciona,','https://unicen.edu.bo/','[\"Abrir el navegador: Entra a la aplicación de Chrome \",\"Ingresar a la página de unicen,luego entrar al menú e ingresar al apartado de col\",\"Presiona el apartado de centro de oportunidades laborales \",\"Espera a que cargue la página, luego desliza asia abajo y ubica los botones de registrar y requisitos \",\"Presiona los botones de registrar y requisitos \",\"Verifica que los botones no están funcionando correctamente \"]','Al tocar el botón regístrate, la página debería abrir inmediatamente el formulario de inscripción para el programa. Al tocar el botón requisitos, debería llevarte de forma automática a la sección donde se listan los documentos necesarios para los estudiantes.','media','Delta','bloqueado',NULL,21,41,'2026-06-06 09:16:04','2026-06-06 05:45:48','2026-06-09 20:35:52'),(103,'Validar caracteres numéricos en campo de \"Apellido Materno \" de la función \"REGISTRATE AQUÍ\"','Verificar que el campo \"Apellido Materno\" impida el ingreso y envió de datos puramente numéricos','Tener cargada la pagina de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la página principal\",\"Hacer clic en el CTA \\\"REGISTRATE AQUÍ\\\" para ingresar  al formulario de Google Docs\",\"Llenar el campo \\\"Apellido Materno\\\" ingresando caracteres numéricos (Ej. 1234)\",\"Completar el resto de los campos obligados del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\"\"]','El sistema debe validar el  campo y desplegar una alerta de error que indique: \"El apellido materno no puede contener solo números\" o \"Formato inválido\"','media','Delta','fallido','Fallo de validación: El campo \"Apellido Materno\" acepta caracteres numéricos independientes y permite continuar con el registro de la solicitud sin lanzar advertencias de formato inválido.',19,19,'2026-06-11 22:13:10','2026-06-09 20:35:50','2026-06-11 22:13:10'),(104,'Validar caracteres numéricos en campo de \"Nombre\" de la función  \"REGISTRATE AQUÍ\"','Verificar que el campo \"Nombre\" impida  el ingreso y envío de datos puramente numéricos','Tener cargada la página de UNICEN\nhttps://unicen.edu.bo/','[\"Dirigirse al Slider de la página principal\",\"Hacer clip en el CTA \\\"REGISTRATE AQUÍ\\\" para ingresar al formato de Google Docs \",\"Llenar el campo \\\"Nombre\\\"  ingresando caracteres numéricos (Ej. 1234)\",\"Completar el resto de los campos obligatorios del formulario con datos validos\",\"Hacer clip en el botón de \\\"Enviar\\\"\"]','El sistema debe validar el campo y desplegar una alerta de error que indique: \"El apellido paterno no puede contener solo números\" o \"Formato invalido\"','media','Delta','fallido','Fallo de validación: El campo \"Nombre\" acepta caracteres numéricos independientes y permite continuar con el registro de la solicitud sin lanzar advertencias de formato inválido.',19,19,'2026-06-11 22:12:29','2026-06-09 20:45:41','2026-06-11 22:12:29');
