INSERT INTO `tareas` VALUES (1,16,3,'Ejercicios de Circuitos','Realizar la serie de ejercicios circuitos logicos','2026-04-28 07:11:46','2026-04-29','Cuaderno_CircuitVerse_50ejercicios.docx','/uploads/1777374706321-987713521.docx','word','2026-04-28 11:11:46'),(2,16,3,'Ejercicio Inicio Circuito','Realizar y mostrar ejercicio ','2026-04-28 09:02:56','2026-04-28',NULL,NULL,NULL,'2026-04-28 13:02:56'),(3,15,3,'Circuito A ','Ejercicio de Cirucuito A','2026-04-28 10:15:42','2026-04-28',NULL,NULL,NULL,'2026-04-28 14:15:42'),(4,15,3,'50 Ejercicios Circuito',NULL,'2026-04-28 16:33:41','2026-05-01',NULL,NULL,NULL,'2026-04-28 20:33:41'),(6,4,8,'PRÁCTICA 1','Cada alumno tiene que entrar al curso con una fotocopia de la práctica\r\nEl docente indicará a cada alumno que ejercicios tiene que resolver\r\nLa presentación es individual en cuaderno en hoja tamaño carta\r\nRecordar que cada práctica vale 15 puntos','2026-04-29 19:34:57','2026-03-23','FUNCIONES.docx','/uploads/1777505697711-747316591.docx','word','2026-04-29 23:34:57'),(7,4,8,'PRÁCTICA 2','1) Sube la práctica en PDF\r\n2) Toma en cuenta la fecha de presentación\r\n3)En cada ejercicio debe poner su nombre','2026-04-29 19:38:53','2026-04-06','PRACTICA -LÃMITES - GR A.docx','/uploads/1777505933241-393013904.docx','word','2026-04-29 23:38:53'),(8,4,8,'PRÁCTICA 3','Indica las 7 reglas principales de derivadas','2026-04-29 19:48:56','2026-04-20','PRÃCTICA 3.docx','/uploads/1777506536121-477470950.docx','word','2026-04-29 23:48:56'),(10,6,8,'PRÁCTICA 1','    Cada alumno tiene que entrar al curso con una fotocopia de la práctica\r\n    El docente indicará a cada alumno que ejercicios tiene que resolver\r\n    La presentación es individual en cuaderno en hoja tamaño carta\r\n    Recordar que cada práctica vale 15 puntos\r\n\r\n','2026-04-29 19:59:01','2026-03-20','FUNCIONES.pdf','/uploads/1777507141628-407251587.pdf','pdf','2026-04-29 23:59:01'),(11,6,8,'PRÁCTICA 2','Sube la práctica en PDF\r\nToma en cuenta la fecha de presentación\r\nEn cada ejercicio debe poner su nombre','2026-04-29 20:01:35','2026-04-07','PRACTICA -LÃMITES - GR B.pdf','/uploads/1777507295507-203683333.pdf','pdf','2026-04-30 00:01:35'),(13,6,8,'PRÁCTICA 3','Conoce las 7 reglas principales de derivadas','2026-04-29 20:03:58','2026-04-27','PRÃCTICA 3.docx','/uploads/1777507438321-507197841.docx','word','2026-04-30 00:03:58'),(14,6,8,'PRÁCTICA 4','Resuelve 4 ejercicios, en los ejercicios 1 al 3\r\nSimplifica las expresiones algebraicas\r\nPresenta en tu cuaderno','2026-04-29 20:06:49','2026-04-30','PRACTICA 3-DERIVADAS-GR B.pdf','/uploads/1777507609022-680547846.pdf','pdf','2026-04-30 00:06:49'),(15,7,6,'ANALISIS DE MACRO Y MICRO ENTORNO',NULL,'2026-04-30 11:38:50','2026-04-30',NULL,NULL,NULL,'2026-04-30 15:38:50'),(16,5,6,'ANALISIS DE MACRO Y MICRO ENTORNO',NULL,'2026-04-30 11:39:01','2026-04-30',NULL,NULL,NULL,'2026-04-30 15:39:01'),(17,5,6,'MPC Y FODA',NULL,'2026-05-04 08:40:00','2026-05-07',NULL,NULL,NULL,'2026-05-04 12:40:00'),(18,7,6,'MPC Y FODA',NULL,'2026-05-04 08:40:34','2026-05-07',NULL,NULL,NULL,'2026-05-04 12:40:34'),(19,16,3,'Realizar un documento de como conectarse por zoom y meets y camara encendida','documento necesario para pasar clases el dia 06/06/2026','2026-05-05 08:12:25','2026-05-05',NULL,NULL,NULL,'2026-05-05 12:12:25'),(20,16,3,'Realizar 5 ejercicios con circuitos y enviarlas como entregado para la practica de hoy','grupo de 2 o 3 integrantes, en formato word ','2026-05-05 08:13:05','2026-05-05',NULL,NULL,NULL,'2026-05-05 12:13:05'),(21,16,3,'Resolver ejercicios 5 ejercicios','Entrega individual','2026-05-05 08:58:06','2026-05-05',NULL,NULL,NULL,'2026-05-05 12:58:06'),(22,15,3,'Realizar una investigacion como encender la camara y el microfono para zoom y meets','Documento a detalle minimo 10 hojas en word, con caratula trabajo individual, con derecho a pasar clases la sgte clases','2026-05-05 09:44:27','2026-05-05',NULL,NULL,NULL,'2026-05-05 13:44:27'),(23,15,3,'Realizar 50 ejercicicios de circuitos para entregar el dia de hoy ','los ejercicios se subiran al sistema y entrega individual','2026-05-05 09:45:39','2026-05-05','Cuaderno_Circuit_50ejercicios_NUEVO.docx','/uploads/1777988739299-730817827.docx','word','2026-05-05 13:45:39'),(24,14,5,'TAREA 6: CONCEPTOS Y MAPAS','INSTRUCCIONES\r\n1. ELABORAR DOS MAPAS EN BASE A LA TEORIA DEL ARRCHIVO DE WORD.\r\n2. ORGANIZAR GRUPOS DE 3 PERSONAS\r\n3. USAR HOJAS TAMAÑO CARTA U OFICIO\r\n4. ELABORAR UN MAPA CONCEPTUAL EN BASE A LA ORGANIZACIÓN JEARQUICA.\r\n5. ELABORAR UN MAPA MENTAL USANDO PALABRAS  CLAVE\r\n6. USAR COLORES.\r\n7. AMBOS MAPAS SE ESCANEAN Y ENTREGAN A ESTA TAREA.. SOLO DEBE ENVIAR 1 INTEGRANTE DEL GRUPO.\r\n8. SE ENTREGA AL DOCENTE AMBAS HOJAS CON LOS MAPAS., ANOTANDO LOS NOMBRES DE LOS INTEGRABTES','2026-05-06 10:28:09','2026-05-07','TAREA 6_CONCEPTOS Y MAPAS_GRUPO B.docx','/uploads/1778077689077-887243317.docx','word','2026-05-06 14:28:09'),(25,13,5,'TAREA 7: CONCEPTOS Y MAPAS','INSTRUCCIONES 1. ELABORAR DOS MAPAS EN BASE A LA TEORIA DEL ARCHIVO DE WORD. 2. ORGANIZAR GRUPOS DE 3 PERSONAS 3. USAR HOJAS TAMAÑO CARTA U OFICIO 4. ELABORAR UN MAPA CONCEPTUAL EN BASE A LA ORGANIZACIÓN JERARQUICA. 5. ELABORAR UN MAPA MENTAL USANDO PALABRAS CLAVE 6. USAR COLORES. 7. AMBOS MAPAS SE ESCANEAN Y ENTREGAN A ESTA TAREA. 7. SOLO DEBE ENVIAR 1 INTEGRANTE DEL GRUPO. 8. SE ENTREGA AL DOCENTE AMBAS HOJAS CON LOS MAPAS., ANOTANDO LOS NOMBRES DE LOS INTEGRANTES.','2026-05-06 17:11:34','2026-05-07','TAREA 7_CONCEPTOS Y MAPAS_GRUPO A - copia.docx','/uploads/1778101894814-833538395.docx','word','2026-05-06 21:11:34'),(26,14,5,'TAREA 7: USO DE SUBRUTINAS_JUEGOS','INSTRUCCIONES\r\n1.	ESTA PROHIBIDO EL USO DE COLECCIONES= LISTAS, TUPLAS Y DICCIONARIOS.\r\n2.	DEBEN EMPLEAR MINIMO 3 MÓDULOS EN SU SOLUCIÓN.\r\n3.	DEBEN REALIZAR LA VALIDACION DE LOS DATOS QUE VIENEN DE TECLADO\r\n4.	DEBEN ELABORAR DOS SOLUCIONES UNA CON USO DE FUNCIONES Y LA OTRA SIN FUNCIONES\r\n5.	DEBEN EXPLICAR LINEA POR LINEA CADA PROGRAMA.\r\n6.	DEBEN EXPLICAR LAS DIFERENCIAS ENTRE AMBOS PROGRAMAS.\r\n7.	DEBEN RESPONDER ¿CUÁL DE LAS DOS SOLUCIONES ES MEJOR Y POR QUÉ?','2026-05-08 08:06:48','2026-05-13','TAREA 7_USO DE SUBRUTINAS_JUEGOS.docx','/uploads/1778242008101-571981250.docx','word','2026-05-08 12:06:48'),(27,10,4,'PRACTICE # 4: COMPARATIVE ADJECTIVES','Practice #4 was about comparative adjectives: rules and sentences in context. (ya entregaron esta práctica, no deben subirla nuevamente.)','2026-05-09 18:24:29',NULL,'4. PRACTICE # 4 COMPARATIVE ADJECTIVES .pdf','/uploads/1778365469431-242316137.pdf','pdf','2026-05-09 22:24:29'),(28,10,4,'PRACTICE # 5: SUPERLATIVE ADJECTIVES','Practice #5 was about superlative adjectives: rules and sentences in context. (ya entregaron la práctica, no deben subir nuevamente)','2026-05-09 18:26:28',NULL,'1. PRACTICE 5 SUPERLATIVE ADJECTIVES.pdf','/uploads/1778365588750-556439525.pdf','pdf','2026-05-09 22:26:28'),(29,10,4,'PRACTICE # 5.1: Comparative & Superlative Adjectives (Song Activity) ','We identified comparative and superlative adjectives in a song. We also practiced pronunciation. (NO deben subir nuevamente la práctica, ya la entregaron.)','2026-05-09 18:29:26',NULL,'cancion.pdf','/uploads/1778365766840-68893508.pdf','pdf','2026-05-09 22:29:26'),(33,12,4,'PRACTICE # 4: COMPARATIVE ADJECTIVES','This practice was about comparative adjectives: rules and sentences in context. (Ya entregaron esta práctica. NO deben subirla nuevamente)','2026-05-09 18:37:10',NULL,'4. PRACTICE # 4 COMPARATIVE ADJECTIVES .pdf','/uploads/1778366230732-825543844.pdf','pdf','2026-05-09 22:37:10'),(34,12,4,'PRACTICE # 5: SUPERLATIVE ADJECTIVES','This practice was about superlative adjectives: rules and sentences in context. (ya entregaron esta práctica, NO deben subirla nuevamente)','2026-05-09 18:39:07',NULL,'1. PRACTICE 5 SUPERLATIVE ADJECTIVES.pdf','/uploads/1778366347344-857606319.pdf','pdf','2026-05-09 22:39:07'),(35,12,4,'PRACTICE # 5.1: Comparative & Superlative Adjectives (song activity)','We identified comparative and superlative adjectives in a song. We also practiced pronunciation. (Ya entregaron esta práctica, NO deben subirla nuevamente)','2026-05-09 18:41:27',NULL,'cancion.pdf','/uploads/1778366487557-530217953.pdf','pdf','2026-05-09 22:41:27'),(36,12,4,'PRACTICE # 6: WHAT TIME IS IT?','Last class, we learned that telling time is important in this career. Please upload your practice here. (SUBAN LA PRÁCTICA A ESTE ESPACIO EN FORMATO PDF)','2026-05-09 18:43:13','2026-05-11',NULL,NULL,NULL,'2026-05-09 22:43:13'),(37,4,8,'PRÁCTICA  4',NULL,'2026-05-09 18:44:25','2026-05-19','PRACTICA 4-DERIVADAS-GR A.pdf','/uploads/1778366665099-577855565.pdf','pdf','2026-05-09 22:44:25'),(38,10,4,'PRACTICE # 6: WHAT TIME IS IT?','Last class, we learned that telling time is important in this career. Please upload your practice here. (SUBAN LA PRÁCTICA A ESTE ESPACIO EN FORMATO PDF)','2026-05-09 18:45:33','2026-05-11','PRACTICE 6 WHAT TIME IS IT.pdf','/uploads/1778366733932-688399285.pdf','pdf','2026-05-09 22:45:33'),(41,5,6,'CASO 1',NULL,'2026-05-11 08:11:56','2026-05-11','CASOS EMP.pdf','/uploads/1778501516442-138709899.pdf','pdf','2026-05-11 12:11:56'),(44,16,3,'Ejercicios E/S - Procesadores','El trabajo debe incluir:\r\n\r\nTipos de procesadores\r\nIntel Core i3, i5, i7, i9\r\nAMD Ryzen 3, 5, 7, 9\r\nOtros procesadores que encuentren, como Intel Celeron, Pentium, Xeon, AMD Athlon, Threadripper, etc.\r\nGeneraciones de procesadores\r\nExplicar qué significa que un procesador sea de una generación específica.\r\nEjemplo: Intel Core i9 de 7.ª generación, 10.ª generación, 12.ª generación, etc.\r\nCómo identificar un procesador\r\nExplicar cómo se lee el nombre o modelo de un procesador.\r\nEjemplo: Intel Core i7-7700\r\n\r\nComparación\r\nRealizar una tabla comparativa con al menos 5 procesadores.\r\nLa tabla debe incluir:\r\nMarca\r\nModelo\r\nGeneración\r\nCantidad de núcleos\r\nFrecuencia o velocidad\r\nUso recomendado: oficina, juegos, diseño, programación, servidores, etc.\r\nConclusión\r\nExplicar cuál procesador consideran mejor para una computadora de uso estudiantil y por qué.\r\n\r\nFormato de entrega:\r\nEl trabajo debe presentarse en digital fuentes de información consultadas.\r\n\r\nCantidad de hojas 3 maximo','2026-05-13 15:41:24','2026-05-13',NULL,NULL,NULL,'2026-05-13 19:41:24'),(45,7,6,'CASO 1',NULL,'2026-05-14 09:39:54','2026-05-14','CASOS EMP.pdf','/uploads/1778765994517-292354455.pdf','pdf','2026-05-14 13:39:54'),(46,7,6,'GESTION ADMINISTRATIVA',NULL,'2026-05-14 21:52:02','2026-05-21',NULL,NULL,NULL,'2026-05-15 01:52:02'),(47,5,6,'GESTION ADMINISTRATIVA',NULL,'2026-05-14 21:52:20','2026-05-21',NULL,NULL,NULL,'2026-05-15 01:52:20'),(48,15,3,'Parte I - Armar un ordenador','Utilizar el simulador y armar tu propio ordenador con componentes','2026-05-15 12:33:55','2026-05-15',NULL,NULL,NULL,'2026-05-15 16:33:55'),(49,13,5,'TAREA 8: CUESIONARIO DE FFUNCIONES Y COLECCIONES','CADA ESTTUDIANTE DEBE SUBIRR EL EXCANEO DE SU DOCUMENTO','2026-05-19 23:46:05','2026-05-20','TAREA8_Cuestionario de funciones y colecciones.docx','/uploads/1779248765737-936856429.docx','word','2026-05-20 03:46:05'),(50,14,5,'TAREA 8 CUESTIONARIO','Escanear y enviar su ciestionario revisado','2026-05-22 11:12:47','2026-05-22',NULL,NULL,NULL,'2026-05-22 15:12:47'),(51,13,5,'TAREA 9: DOCUMENTO WORD TAREA GRUPAL','1. ELABORAR EL DOCUMENTO Y ENVIAR ESE ARCHIVO COS LOS PUNTOS ESTABLECIDOS.\r\n2. SOLO UNO DE LOS INTEGRANTES DEBE ENVIAR.\r\n3. FECHA DE CIERRE : DOMINGO  24 DE MAYO DE 2026 HRS : 23: 59 P.M','2026-05-22 22:40:12','2026-05-24','TAREA  NRO 9 DOCUMENTO EN WORD.docx','/uploads/1779504012242-546146831.docx','word','2026-05-23 02:40:12'),(52,13,5,'TAREA 10: PROGRAMA Y PRESENTACION','1.  ELABORAR UN DOCUMENTO CON EL CODIGO DEL PROGRAMA  Y LA PRESENTACION  EN POWERPOINT PARA ENVIAR\r\n2. SOLAMENTE UN INTEGRANTE DEBE ENVIAR SU TRABAJO\r\n3. FECHA DE CIERRE: 24/05/2026 HRS 23:59 P.M','2026-05-22 22:43:39','2026-05-24','TAREA  NRO 10 PROGRAMA Y PRESENTACIÃN.docx','/uploads/1779504219820-382960371.docx','word','2026-05-23 02:43:39'),(53,14,5,'TAREA 9: DOCUMENTO DE WORD TAREA GRUPAL','1. ELABORAR EL DOCUMENTO Y ENVIAR ESE ARCHIVO COS LOS PUNTOS ESTABLECIDOS. 2. SOLO UNO DE LOS INTEGRANTES DEBE ENVIAR. 3. FECHA DE CIERRE : MIERCOLES 27 DE MAYO DE 2026 HRS : 23: 59 P.M','2026-05-22 22:58:57','2026-05-27','TAREA  NRO 9 DOCUMENTO EN WORD.docx','/uploads/1779505137411-777007363.docx','word','2026-05-23 02:58:57'),(54,14,5,'TAREA 10 : PROGRAMA Y EXPOSICION','1. ELABORAR UN DOCUMENTO CON EL CODIGO DEL PROGRAMA Y LA PRESENTACION EN POWERPOINT PARA ENVIAR 2. SOLAMENTE UN INTEGRANTE DEBE ENVIAR SU TRABAJO 3. FECHA DE CIERRE: 24/05/2026 HRS 23:59 P.M','2026-05-22 23:39:45','2026-05-28','TAREA  NRO 10 PROGRAMA Y PRESENTACIÃN.docx','/uploads/1779507585373-80780111.docx','word','2026-05-23 03:39:45'),(55,14,5,'ULTIMA TAREA','INSTRUCCIONES\r\n\r\nresolver el ejercico usando colecciones\r\nresolver el ejercicio usando la libreria validar\r\nresolver el ejercicio usando funciones def\r\nresolver el ejercicio usando la libreria numpy\r\nresolver el ejercicio usando la libreria matplotlib','2026-06-12 09:59:51','2026-06-12','ULTIMA TAREA.docx','/uploads/1781272791029-677597853.docx','word','2026-06-12 13:59:51');
