INSERT INTO `unidades_instruccion` VALUES (1,'Circuitos Lógicos','Simulador interactivo de circuitos logicos. Ingresa una tabla de verdad y visualiza el circuito equivalente en tiempo real. Puedes alternar las entradas para ver como se propagan las senales.','simulador',NULL,1,1,NULL,'2026-04-27 07:03:43'),(2,'Cálculo — Derivadas','Simulador interactivo: ingresa una función f(x) y un punto P para calcular la derivada, pendiente, recta tangente, recta normal y visualizar la gráfica en tiempo real.','simulador',NULL,2,1,NULL,'2026-05-14 20:31:06'),(3,'Armar una PC','Simulador interactivo de ensamblaje de computadoras: selecciona procesador, tarjeta madre, RAM, almacenamiento, GPU, fuente, refrigeración, gabinete y más. El sistema verifica compatibilidad, indica si la PC enciende y genera un reporte de gama y precio estimado.','simulador',NULL,3,1,NULL,'2026-05-14 20:31:27'),(6,'Canvas inteligente — Modelo de negocio','Construye tu modelo Canvas usando IA como asesor. Selecciona un rol de asesor IA, completa cada bloque del Business Model Canvas y copia prompts generados para usar con ChatGPT, Claude o Gemini.','simulador',NULL,4,1,1,'2026-05-25 09:43:29'),(7,'Analizador de mercado con IA — Bolivia','Ingresa tu idea de negocio y la IA analiza negocios similares en Bolivia, tendencias del mercado y viabilidad de éxito. Genera un reporte descargable en PDF.','simulador',NULL,5,1,1,'2026-05-25 09:43:42'),(8,'Sprint de Validación Lean','Formula tu hipótesis de negocio, diseña un experimento ágil y deja que la IA simule 8 clientes potenciales para validar tu idea. Obtén un veredicto: Perseverar, Pivotar parcialmente o Pivotar.','simulador',NULL,6,1,1,'2026-05-27 10:36:34'),(9,'Pitch Arena','Responde 6 preguntas de diagnóstico sobre tu idea, recibe un escenario único de pitch generado por IA (tipo de evaluador, condición especial, pregunta crítica) y presenta tu propuesta. Obtén una evaluación en 5 dimensiones con el pitch ideal y lineamientos de éxito y fracaso.','simulador',NULL,7,1,1,'2026-05-27 10:36:48'),(10,'Startup Cards','La IA genera 15 cartas de rubros de negocio. Elige 5 que combinen bien, define el nombre, colores y eslogan de tu empresa, y la IA construye el análisis de mercado para Cochabamba, sugiere personajes clave bolivianos reales como directivos y arma el organigrama jerárquico.','simulador',NULL,8,1,1,'2026-05-29 17:11:29'),(11,'Mercado Virtual','Simulación interactiva de ventas: elige un sector, selecciona tus productos y negocia con 5 compradores reales de Cochabamba generados por IA. Practica habilidades de negociación y pitch de ventas.','simulador',NULL,9,1,NULL,'2026-05-29 17:12:02'),(12,'QA Lab','Aprende gestión de calidad de software: reporta bugs con campos estándar (severidad, prioridad, ambiente, pasos para reproducir) y crea/ejecuta test cases. Elige tu rol QA Tester o Developer para una experiencia realista de trabajo en equipo.','simulador',NULL,10,1,NULL,'2026-05-30 12:13:15'),(13,'Buscador PICO','B?squeda bibliogr?fica sistem?tica usando metodolog?a PICO. La IA genera t?rminos MeSH, ejecuta la b?squeda en bases de datos biom?dicas y produce un informe de evidencia con fuentes, PMIDs, DOI y nivel de recomendaci?n Oxford CEBM.','simulador',NULL,11,1,NULL,'2026-06-13 08:47:52'),(14,'Sala de Operaciones','Simulador quir?rgico con IA: enfrenta una emergencia m?dica aleatoria, conforma tu equipo seleccionando personal real, toma decisiones cr?ticas en cada fase de la operaci?n y obt?n un informe educativo con an?lisis de cada decisi?n.','simulador',NULL,12,1,NULL,'2026-06-13 09:46:12');
